CREATE TABLE IF NOT EXISTS ik_d1_erasure_progress (id TEXT PRIMARY KEY,destination TEXT NOT NULL,request_hash TEXT NOT NULL,generation TEXT NOT NULL,phase TEXT NOT NULL CHECK(phase IN ('index','values','sealed','complete')),index_rows INTEGER NOT NULL CHECK(index_rows>=0),value_rows INTEGER NOT NULL CHECK(value_rows>=0),revision INTEGER NOT NULL CHECK(revision=index_rows+value_rows),records_erased INTEGER NOT NULL CHECK(records_erased>=0),field_matches_json TEXT NOT NULL CHECK(json_valid(field_matches_json)),created_at TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_progress_insert BEFORE INSERT ON ik_d1_erasure_progress WHEN EXISTS(SELECT 1 FROM ik_d1_erasure_progress WHERE id=NEW.id) BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_OPERATION_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_progress_binding BEFORE UPDATE ON ik_d1_erasure_progress WHEN NEW.id IS NOT OLD.id OR NEW.destination IS NOT OLD.destination OR NEW.request_hash IS NOT OLD.request_hash OR NEW.created_at IS NOT OLD.created_at OR OLD.phase='complete' BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_OPERATION_CHANGED'); END;
CREATE TRIGGER IF NOT EXISTS ik_d1_erasure_progress_delete BEFORE DELETE ON ik_d1_erasure_progress WHEN OLD.phase='complete' BEGIN SELECT RAISE(ABORT,'IMPORT_ERASURE_OPERATION_CHANGED'); END;

-- Blotter practice workflow. Money is integer AUD cents; dates are YYYY-MM-DD.
-- Due dates are recorded by people, never computed.
CREATE TABLE b_members(
 email TEXT PRIMARY KEY, name TEXT NOT NULL,
 role TEXT NOT NULL CHECK(role IN ('reviewer','preparer')), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1))
);
-- Hourly rates, including the principal's. Time entries snapshot the rate in force.
CREATE TABLE b_rates(
 email TEXT PRIMARY KEY, rate_cents INTEGER NOT NULL CHECK(rate_cents BETWEEN 0 AND 1000000),
 updated_by TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE b_guard(id TEXT PRIMARY KEY, ok INTEGER NOT NULL CHECK(ok=1));
CREATE TABLE b_meta(id INTEGER PRIMARY KEY CHECK(id=1), client_revision INTEGER NOT NULL DEFAULT 0);
INSERT INTO b_meta(id) VALUES(1);

CREATE TABLE b_clients(
 id TEXT PRIMARY KEY, name TEXT NOT NULL, abn TEXT NOT NULL DEFAULT '',
 contact_name TEXT NOT NULL DEFAULT '', contact_email TEXT NOT NULL DEFAULT '',
 source TEXT NOT NULL DEFAULT 'native', revision TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TRIGGER b_client_insert AFTER INSERT ON b_clients BEGIN UPDATE b_meta SET client_revision=client_revision+1 WHERE id=1; END;
CREATE TRIGGER b_client_update AFTER UPDATE ON b_clients BEGIN UPDATE b_meta SET client_revision=client_revision+1 WHERE id=1; END;
CREATE TRIGGER b_client_delete AFTER DELETE ON b_clients BEGIN UPDATE b_meta SET client_revision=client_revision+1 WHERE id=1; END;

CREATE TABLE b_templates(
 id TEXT PRIMARY KEY, name TEXT NOT NULL,
 recurrence TEXT NOT NULL CHECK(recurrence IN ('monthly','quarterly','annual')),
 steps TEXT NOT NULL CHECK(json_valid(steps)), requests TEXT NOT NULL CHECK(json_valid(requests)),
 fee_cents INTEGER NOT NULL DEFAULT 0 CHECK(fee_cents BETWEEN 0 AND 100000000),
 created_by TEXT NOT NULL, created_at TEXT NOT NULL
);

CREATE TABLE b_jobs(
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES b_clients(id), template_id TEXT NOT NULL REFERENCES b_templates(id),
 title TEXT NOT NULL, period_start TEXT NOT NULL, period_label TEXT NOT NULL,
 due_date TEXT NOT NULL, due_note TEXT NOT NULL,
 preparer_email TEXT NOT NULL, reviewer_email TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('open','review','signed_off')),
 fee_cents INTEGER NOT NULL CHECK(fee_cents BETWEEN 0 AND 100000000),
 rolled_from TEXT REFERENCES b_jobs(id), revision TEXT NOT NULL,
 created_by TEXT NOT NULL, created_channel TEXT NOT NULL CHECK(created_channel IN ('person','agent')), created_at TEXT NOT NULL,
 submitted_by TEXT, submitted_at TEXT, signed_off_by TEXT, signed_off_at TEXT, sign_off_note TEXT,
 UNIQUE(client_id,template_id,period_start),
 CHECK(status<>'signed_off' OR (signed_off_by IS NOT NULL AND sign_off_note IS NOT NULL))
);
CREATE INDEX b_jobs_due ON b_jobs(due_date);
CREATE TRIGGER b_jobs_transition BEFORE UPDATE OF status ON b_jobs
 WHEN NEW.status<>OLD.status AND NOT ((OLD.status='open' AND NEW.status='review') OR (OLD.status='review' AND NEW.status IN ('open','signed_off')))
 BEGIN SELECT RAISE(ABORT,'invalid job transition'); END;
CREATE TRIGGER b_jobs_signed_off BEFORE UPDATE ON b_jobs WHEN OLD.status='signed_off'
 BEGIN SELECT RAISE(ABORT,'signed-off jobs are immutable'); END;
CREATE TRIGGER b_jobs_delete BEFORE DELETE ON b_jobs BEGIN SELECT RAISE(ABORT,'job history is immutable'); END;

CREATE TABLE b_job_steps(
 job_id TEXT NOT NULL REFERENCES b_jobs(id), ordinal INTEGER NOT NULL, label TEXT NOT NULL,
 done_by TEXT, done_at TEXT, PRIMARY KEY(job_id,ordinal)
);
CREATE TABLE b_requests(
 id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES b_jobs(id), ordinal INTEGER NOT NULL, label TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('requested','received','accepted')),
 note TEXT NOT NULL DEFAULT '', updated_by TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(job_id,ordinal)
);
-- Base64 expands the 1 MiB byte cap to at most 1,398,104 characters. Erasure
-- removes bytes only; names, hashes and provenance remain.
CREATE TABLE b_files(
 id TEXT PRIMARY KEY, request_id TEXT NOT NULL REFERENCES b_requests(id), job_id TEXT NOT NULL REFERENCES b_jobs(id),
 name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL CHECK(size BETWEEN 1 AND 1048576), sha256 TEXT NOT NULL,
 content_base64 TEXT CHECK(length(content_base64)<=1398104),
 uploaded_by TEXT NOT NULL, channel TEXT NOT NULL CHECK(channel IN ('portal','person')), uploaded_at TEXT NOT NULL,
 erased_at TEXT, erased_by TEXT, erase_reason TEXT
);
CREATE INDEX b_files_job ON b_files(job_id);
CREATE TRIGGER b_files_immutable BEFORE UPDATE ON b_files
 WHEN NEW.id IS NOT OLD.id OR NEW.request_id IS NOT OLD.request_id OR NEW.job_id IS NOT OLD.job_id OR NEW.name IS NOT OLD.name
 OR NEW.mime IS NOT OLD.mime OR NEW.size IS NOT OLD.size OR NEW.sha256 IS NOT OLD.sha256 OR NEW.uploaded_by IS NOT OLD.uploaded_by
 OR NEW.channel IS NOT OLD.channel OR NEW.uploaded_at IS NOT OLD.uploaded_at OR NEW.content_base64 IS NOT NULL OR OLD.erased_at IS NOT NULL
 BEGIN SELECT RAISE(ABORT,'uploaded files are immutable'); END;
CREATE TRIGGER b_files_delete BEFORE DELETE ON b_files BEGIN SELECT RAISE(ABORT,'uploaded files are immutable'); END;

-- Client upload links: only a digest of the secret is stored. Not archived.
CREATE TABLE b_portal_links(
 id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES b_jobs(id), digest TEXT NOT NULL UNIQUE,
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT
);
CREATE TABLE b_reminders(
 id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES b_jobs(id), to_email TEXT NOT NULL,
 outstanding TEXT NOT NULL CHECK(json_valid(outstanding)), message TEXT NOT NULL,
 delivery TEXT NOT NULL, sent_by TEXT NOT NULL, proposal_id TEXT, sent_at TEXT NOT NULL
);

CREATE TABLE b_time(
 id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES b_jobs(id), person_email TEXT NOT NULL,
 date TEXT NOT NULL, minutes INTEGER NOT NULL CHECK(minutes BETWEEN 1 AND 1440),
 rate_cents INTEGER NOT NULL CHECK(rate_cents BETWEEN 0 AND 1000000), amount_cents INTEGER NOT NULL CHECK(amount_cents>=0),
 description TEXT NOT NULL, created_by TEXT NOT NULL, created_channel TEXT NOT NULL CHECK(created_channel IN ('person','agent')), created_at TEXT NOT NULL
);
CREATE INDEX b_time_job ON b_time(job_id,date);
CREATE TRIGGER b_time_immutable BEFORE UPDATE ON b_time BEGIN SELECT RAISE(ABORT,'time entries are immutable'); END;

CREATE TABLE b_exports(
 id TEXT PRIMARY KEY, title TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','approved','void')),
 snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), total_cents INTEGER NOT NULL,
 csv TEXT, csv_sha256 TEXT, revision TEXT NOT NULL,
 prepared_by TEXT NOT NULL, prepared_channel TEXT NOT NULL CHECK(prepared_channel IN ('person','agent')), prepared_at TEXT NOT NULL,
 approved_by TEXT, approved_at TEXT, review_note TEXT, voided_by TEXT, voided_at TEXT, void_reason TEXT,
 CHECK(status<>'approved' OR (csv IS NOT NULL AND csv_sha256 IS NOT NULL AND approved_by IS NOT NULL AND review_note IS NOT NULL))
);
-- One export per billable source: 'time:<id>' or 'fee:<job id>'.
CREATE TABLE b_export_sources(source_key TEXT PRIMARY KEY, export_id TEXT NOT NULL REFERENCES b_exports(id));
CREATE TRIGGER b_exports_transition BEFORE UPDATE ON b_exports
 WHEN NOT (OLD.status='draft' AND NEW.status IN ('approved','void'))
 OR NEW.snapshot<>OLD.snapshot OR NEW.total_cents<>OLD.total_cents OR NEW.prepared_by<>OLD.prepared_by OR NEW.prepared_at<>OLD.prepared_at
 BEGIN SELECT RAISE(ABORT,'approved exports are immutable'); END;
CREATE TRIGGER b_exports_delete BEFORE DELETE ON b_exports BEGIN SELECT RAISE(ABORT,'export history is immutable'); END;
CREATE TRIGGER b_export_sources_release BEFORE DELETE ON b_export_sources
 WHEN NOT EXISTS(SELECT 1 FROM b_exports WHERE id=OLD.export_id AND status='void')
 BEGIN SELECT RAISE(ABORT,'only void exports release sources'); END;
CREATE TRIGGER b_time_delete BEFORE DELETE ON b_time
 WHEN EXISTS(SELECT 1 FROM b_export_sources WHERE source_key='time:'||OLD.id)
 BEGIN SELECT RAISE(ABORT,'exported time is immutable'); END;

CREATE TABLE b_audit(id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, object_id TEXT NOT NULL, detail TEXT NOT NULL, at TEXT NOT NULL);
CREATE TABLE b_agent_keys(id TEXT PRIMARY KEY, label TEXT NOT NULL, digest TEXT NOT NULL UNIQUE, owner_id TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE b_proposals(
 id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('rollforward','reminder','export')), payload TEXT NOT NULL CHECK(json_valid(payload)),
 for_email TEXT NOT NULL, agent_label TEXT NOT NULL,
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','declined')),
 result_id TEXT, decided_by TEXT, decided_at TEXT, decision_note TEXT, created_at TEXT NOT NULL
);

-- Timesheets and period locks (TIME-002). A person submits a week's time; a
-- reviewer or the principal approves or returns each entry with a reason. A
-- closed billing period locks its approved time, and a correction after
-- approval is an adjustment that keeps the original entry. Additive only, so
-- older archives still restore.
CREATE TABLE b_time_status(
 entry_id TEXT PRIMARY KEY REFERENCES b_time(id), person_email TEXT NOT NULL, week_start TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('submitted','approved','returned')),
 submitted_at TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', decided_by TEXT, decided_at TEXT,
 CHECK(status='submitted' OR decided_by IS NOT NULL), CHECK(status<>'returned' OR reason<>'')
);
CREATE INDEX b_time_status_week ON b_time_status(person_email,week_start);
CREATE TABLE b_periods(
 id TEXT PRIMARY KEY, start_date TEXT NOT NULL, end_date TEXT NOT NULL, note TEXT NOT NULL,
 closed_by TEXT NOT NULL, closed_at TEXT NOT NULL, CHECK(end_date>=start_date)
);
CREATE TABLE b_time_adjustments(
 id TEXT PRIMARY KEY, entry_id TEXT NOT NULL REFERENCES b_time(id),
 minutes INTEGER NOT NULL CHECK(minutes<>0 AND minutes BETWEEN -1440 AND 1440), amount_cents INTEGER NOT NULL,
 reason TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE INDEX b_time_adjustments_entry ON b_time_adjustments(entry_id);

-- Internal discussions and review alerts (COLLAB-001). A thread belongs to a
-- client, or to a job and optionally one of its steps, document requests or its
-- review. A correction thread is owned by the job's preparer with a follow-up
-- date. Messages are immutable; a resolved thread keeps its decision. Nothing
-- here is served through the client link. Additive only, so older archives
-- still restore.
CREATE TABLE b_threads(
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES b_clients(id), job_id TEXT REFERENCES b_jobs(id),
 anchor TEXT NOT NULL, title TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('discussion','correction')),
 owner_email TEXT NOT NULL, follow_up_due TEXT, status TEXT NOT NULL CHECK(status IN ('open','resolved')),
 resolution TEXT, resolved_by TEXT, resolved_at TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL,
 CHECK(kind<>'correction' OR (job_id IS NOT NULL AND follow_up_due IS NOT NULL)),
 CHECK(status='open' OR (resolution<>'' AND resolved_by IS NOT NULL AND resolved_at IS NOT NULL))
);
CREATE INDEX b_threads_job ON b_threads(job_id);
CREATE INDEX b_threads_client ON b_threads(client_id);
CREATE TRIGGER b_threads_resolved BEFORE UPDATE ON b_threads WHEN OLD.status='resolved'
 BEGIN SELECT RAISE(ABORT,'resolved threads are immutable'); END;
CREATE TABLE b_thread_messages(
 id TEXT PRIMARY KEY, thread_id TEXT NOT NULL REFERENCES b_threads(id), author_email TEXT NOT NULL,
 body TEXT NOT NULL, mentions TEXT NOT NULL CHECK(json_valid(mentions)), created_at TEXT NOT NULL
);
CREATE INDEX b_thread_messages_thread ON b_thread_messages(thread_id,created_at);
CREATE TRIGGER b_thread_messages_immutable BEFORE UPDATE ON b_thread_messages BEGIN SELECT RAISE(ABORT,'messages are immutable'); END;
CREATE TRIGGER b_thread_messages_delete BEFORE DELETE ON b_thread_messages BEGIN SELECT RAISE(ABORT,'messages are immutable'); END;
CREATE TABLE b_thread_reads(
 thread_id TEXT NOT NULL REFERENCES b_threads(id), email TEXT NOT NULL, read_at TEXT NOT NULL, PRIMARY KEY(thread_id,email)
);
CREATE TABLE b_notifications(
 id TEXT PRIMARY KEY, to_email TEXT NOT NULL, kind TEXT NOT NULL, job_id TEXT, thread_id TEXT,
 summary TEXT NOT NULL, delivery TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE INDEX b_notifications_to ON b_notifications(to_email,created_at);

-- Client groups, tags and firm-defined fields (CRM-002). Field values and tags
-- live on the client row as JSON, so imports, undo and archives carry them with
-- the client. Additive only, so older archives still restore.
ALTER TABLE b_clients ADD COLUMN fields TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(fields) AND json_type(fields)='object');
ALTER TABLE b_clients ADD COLUMN tags TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(tags) AND json_type(tags)='array');
CREATE TABLE b_client_fields(
 key TEXT PRIMARY KEY CHECK(length(key) BETWEEN 1 AND 40), label TEXT NOT NULL,
 type TEXT NOT NULL CHECK(type IN ('text','number','date','choice')), choices TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(choices)),
 required INTEGER NOT NULL CHECK(required IN (0,1)), created_by TEXT NOT NULL, created_at TEXT NOT NULL,
 CHECK(type<>'choice' OR json_array_length(choices)>0)
);
CREATE TABLE b_client_groups(
 id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, created_by TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TABLE b_client_group_members(
 group_id TEXT NOT NULL REFERENCES b_client_groups(id), client_id TEXT NOT NULL,
 relationship TEXT NOT NULL CHECK(relationship IN ('parent','subsidiary','household','member')),
 added_by TEXT NOT NULL, added_at TEXT NOT NULL, PRIMARY KEY(group_id,client_id)
);
CREATE INDEX b_client_group_members_client ON b_client_group_members(client_id);

-- Task assignees, relative dates and instructions (WORK-009). A checklist step
-- is a task: it may be assigned to a job role (preparer, reviewer, manager) or
-- a named person, with start and due dates as whole days relative to the
-- work's start (its period start) or due date. Owners and dates of open tasks
-- are resolved when read, so they follow the job's people and due date; a
-- completed task keeps its completer, time and the dates it had then. A job's
-- manager is its reviewer unless one is named. Additive only, so older
-- archives still restore.
ALTER TABLE b_jobs ADD COLUMN manager_email TEXT;
ALTER TABLE b_job_steps ADD COLUMN assignee_role TEXT CHECK(assignee_role IS NULL OR assignee_role IN ('preparer','reviewer','manager'));
ALTER TABLE b_job_steps ADD COLUMN assignee_email TEXT;
ALTER TABLE b_job_steps ADD COLUMN start_anchor TEXT CHECK(start_anchor IS NULL OR start_anchor IN ('start','due'));
ALTER TABLE b_job_steps ADD COLUMN start_offset INTEGER CHECK(start_offset IS NULL OR start_offset BETWEEN -366 AND 366);
ALTER TABLE b_job_steps ADD COLUMN due_anchor TEXT CHECK(due_anchor IS NULL OR due_anchor IN ('start','due'));
ALTER TABLE b_job_steps ADD COLUMN due_offset INTEGER CHECK(due_offset IS NULL OR due_offset BETWEEN -366 AND 366);
ALTER TABLE b_job_steps ADD COLUMN estimate_minutes INTEGER CHECK(estimate_minutes IS NULL OR estimate_minutes BETWEEN 1 AND 100000);
ALTER TABLE b_job_steps ADD COLUMN instructions TEXT NOT NULL DEFAULT '';
ALTER TABLE b_job_steps ADD COLUMN sop_url TEXT NOT NULL DEFAULT '';
ALTER TABLE b_job_steps ADD COLUMN requires_attachment INTEGER NOT NULL DEFAULT 0 CHECK(requires_attachment IN (0,1));
ALTER TABLE b_job_steps ADD COLUMN client_facing INTEGER NOT NULL DEFAULT 0 CHECK(client_facing IN (0,1));
ALTER TABLE b_job_steps ADD COLUMN done_start_date TEXT;
ALTER TABLE b_job_steps ADD COLUMN done_due_date TEXT;
ALTER TABLE b_job_steps ADD COLUMN done_owner TEXT;
ALTER TABLE b_job_steps ADD COLUMN attachment_name TEXT;
ALTER TABLE b_job_steps ADD COLUMN attachment_mime TEXT;
ALTER TABLE b_job_steps ADD COLUMN attachment_size INTEGER CHECK(attachment_size IS NULL OR attachment_size BETWEEN 1 AND 1048576);
ALTER TABLE b_job_steps ADD COLUMN attachment_sha256 TEXT;
ALTER TABLE b_job_steps ADD COLUMN attachment_base64 TEXT CHECK(attachment_base64 IS NULL OR length(attachment_base64)<=1398104);

-- Enforced staff multi-factor authentication (ACCESS-004). The principal can
-- require a second factor for every staff session. A factor is a TOTP
-- authenticator (its secret sealed under a key derived from SESSION_SECRET)
-- or a passkey/security key (its public key and signature counter); one-time
-- recovery codes are stored only as digests. A session counts as
-- verified only after its own second-factor check. Factors, recovery codes,
-- verified sessions, challenges and failures stay out of every archive. The
-- policy row also holds the firm's session lifetime and idle timeout, in
-- minutes (NULL keeps sign-in's own limit); last activity is kept per session.
CREATE TABLE b_mfa_policy(
 id INTEGER PRIMARY KEY CHECK(id=1), required INTEGER NOT NULL DEFAULT 0 CHECK(required IN (0,1)),
 session_minutes INTEGER CHECK(session_minutes IS NULL OR session_minutes BETWEEN 1 AND 43200),
 idle_minutes INTEGER CHECK(idle_minutes IS NULL OR idle_minutes BETWEEN 1 AND 1440),
 set_by TEXT NOT NULL, set_at TEXT NOT NULL
);
CREATE TABLE b_session_activity(session_id TEXT PRIMARY KEY, seen_at INTEGER NOT NULL);
CREATE TABLE b_mfa_factors(
 id TEXT PRIMARY KEY, email TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('totp','passkey')), label TEXT NOT NULL,
 sealed_secret TEXT, last_step INTEGER NOT NULL DEFAULT 0,
 credential_id TEXT UNIQUE, public_key TEXT CHECK(public_key IS NULL OR json_valid(public_key)), sign_count INTEGER NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL, confirmed_at TEXT, last_used_at TEXT,
 CHECK((kind='totp' AND sealed_secret IS NOT NULL) OR (kind='passkey' AND credential_id IS NOT NULL AND public_key IS NOT NULL))
);
CREATE INDEX b_mfa_factors_email ON b_mfa_factors(email);
CREATE TABLE b_mfa_recovery(
 email TEXT NOT NULL, digest TEXT NOT NULL, created_at TEXT NOT NULL, used_at TEXT, PRIMARY KEY(email,digest)
);
CREATE TABLE b_mfa_sessions(
 session_id TEXT PRIMARY KEY, email TEXT NOT NULL, method TEXT NOT NULL, verified_at TEXT NOT NULL
);
CREATE INDEX b_mfa_sessions_email ON b_mfa_sessions(email);
CREATE TABLE b_mfa_challenges(
 id TEXT PRIMARY KEY, email TEXT NOT NULL, session_id TEXT NOT NULL, purpose TEXT NOT NULL CHECK(purpose IN ('register','verify')),
 challenge TEXT NOT NULL, expires_at TEXT NOT NULL
);
CREATE INDEX b_mfa_challenges_session ON b_mfa_challenges(session_id,purpose);
CREATE TABLE b_mfa_failures(id TEXT PRIMARY KEY, email TEXT NOT NULL, at TEXT NOT NULL);
CREATE INDEX b_mfa_failures_email ON b_mfa_failures(email,at);

-- Firm and personal message templates (MSG-001). A template is a named,
-- categorised subject and body with {{placeholders}}; each edit adds a version
-- with its author, and deleting hides the template but keeps its versions.
-- A reminder records the subject, the rendered text and the template version
-- it used, so later edits never change sent messages. Additive only.
CREATE TABLE b_firm(id INTEGER PRIMARY KEY CHECK(id=1), name TEXT NOT NULL, set_by TEXT NOT NULL, set_at TEXT NOT NULL);
CREATE TABLE b_msg_templates(
 id TEXT PRIMARY KEY, scope TEXT NOT NULL CHECK(scope IN ('firm','personal')), owner_email TEXT,
 name TEXT NOT NULL, category TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>=1),
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, deleted_by TEXT, deleted_at TEXT,
 CHECK((scope='firm' AND owner_email IS NULL) OR (scope='personal' AND owner_email IS NOT NULL))
);
CREATE TABLE b_msg_template_versions(
 template_id TEXT NOT NULL REFERENCES b_msg_templates(id), version INTEGER NOT NULL,
 subject TEXT NOT NULL, body TEXT NOT NULL, author TEXT NOT NULL, created_at TEXT NOT NULL,
 PRIMARY KEY(template_id,version)
);
CREATE TRIGGER b_msg_versions_immutable BEFORE UPDATE ON b_msg_template_versions BEGIN SELECT RAISE(ABORT,'template versions are immutable'); END;
CREATE TRIGGER b_msg_versions_delete BEFORE DELETE ON b_msg_template_versions BEGIN SELECT RAISE(ABORT,'template versions are immutable'); END;
ALTER TABLE b_reminders ADD COLUMN subject TEXT;
ALTER TABLE b_reminders ADD COLUMN template_id TEXT;
ALTER TABLE b_reminders ADD COLUMN template_version INTEGER;

-- Dependencies and conditional workflow (WORK-003). A template task can wait
-- for other tasks of the same job, for accepted client documents and for a
-- prerequisite job of the same client (submitted for review, or signed off),
-- and can apply only when a job question has one of the chosen answers. A
-- reviewer or the principal may record an exception with a reason; it lets a
-- blocked task be worked but completes nothing else. ready_at records when a
-- gated task last became ready. Additive only, so older archives still restore.
ALTER TABLE b_templates ADD COLUMN questions TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(questions));
ALTER TABLE b_job_steps ADD COLUMN after_steps TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(after_steps));
ALTER TABLE b_job_steps ADD COLUMN after_requests TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(after_requests));
ALTER TABLE b_job_steps ADD COLUMN after_template TEXT;
ALTER TABLE b_job_steps ADD COLUMN after_gate TEXT CHECK(after_gate IS NULL OR after_gate IN ('submitted','signed_off'));
ALTER TABLE b_job_steps ADD COLUMN when_question TEXT;
ALTER TABLE b_job_steps ADD COLUMN when_values TEXT CHECK(when_values IS NULL OR json_valid(when_values));
ALTER TABLE b_job_steps ADD COLUMN ready_at TEXT;
ALTER TABLE b_job_steps ADD COLUMN exception_by TEXT;
ALTER TABLE b_job_steps ADD COLUMN exception_at TEXT;
ALTER TABLE b_job_steps ADD COLUMN exception_reason TEXT;
ALTER TABLE b_job_steps ADD COLUMN exception_waived TEXT;
CREATE TABLE b_job_answers(
 job_id TEXT NOT NULL REFERENCES b_jobs(id), key TEXT NOT NULL, ordinal INTEGER NOT NULL, label TEXT NOT NULL,
 options TEXT NOT NULL CHECK(json_valid(options)), value TEXT, answered_by TEXT, answered_at TEXT,
 PRIMARY KEY(job_id,key)
);

-- Running timers (TIME-001). One per person, kept in D1 so it survives closing
-- the browser or app; stopping it records an ordinary time entry. Additive only.
CREATE TABLE b_timers(
 person_email TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES b_jobs(id),
 description TEXT NOT NULL, started_at TEXT NOT NULL
);

-- Time against a task (TIME-001). A time entry or running timer may name one
-- of its job's checklist tasks by ordinal; the job, and so its client, is
-- always recorded. Additive only.
ALTER TABLE b_time ADD COLUMN step_ordinal INTEGER CHECK(step_ordinal IS NULL OR step_ordinal BETWEEN 1 AND 100);
ALTER TABLE b_timers ADD COLUMN step_ordinal INTEGER CHECK(step_ordinal IS NULL OR step_ordinal BETWEEN 1 AND 100);

-- Template attachments (MSG-001). Each template version carries its own files,
-- at most five of up to 1 MiB each; an edit keeps the previous version's files
-- unless it replaces them, so a version's files never change. A reminder
-- records the name, type, size and SHA-256 of every file it was sent with.
-- Additive only.
CREATE TABLE b_msg_template_files(
 template_id TEXT NOT NULL, version INTEGER NOT NULL, ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 1 AND 5),
 name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL CHECK(size BETWEEN 1 AND 1048576), sha256 TEXT NOT NULL,
 content_base64 TEXT NOT NULL CHECK(length(content_base64)<=1398104),
 PRIMARY KEY(template_id,version,ordinal), FOREIGN KEY(template_id,version) REFERENCES b_msg_template_versions(template_id,version)
);
CREATE TRIGGER b_msg_files_immutable BEFORE UPDATE ON b_msg_template_files BEGIN SELECT RAISE(ABORT,'template files are immutable'); END;
CREATE TRIGGER b_msg_files_delete BEFORE DELETE ON b_msg_template_files BEGIN SELECT RAISE(ABORT,'template files are immutable'); END;
ALTER TABLE b_reminders ADD COLUMN attachments TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(attachments));

-- Workload capacity and coverage (CAPACITY-001). Each person's weekly hours
-- and skills; leave, client meetings and internal commitments as dated blocks
-- of weekday minutes; and a review estimate per job beside the task estimates
-- (WORK-009) that make up remaining preparation work. Additive only.
CREATE TABLE b_capacity(
 email TEXT PRIMARY KEY, weekly_minutes INTEGER NOT NULL CHECK(weekly_minutes BETWEEN 0 AND 6000),
 skills TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(skills)), updated_by TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE TABLE b_capacity_blocks(
 id TEXT PRIMARY KEY, email TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('leave','meeting','internal')),
 starts_on TEXT NOT NULL, ends_on TEXT NOT NULL CHECK(ends_on>=starts_on),
 minutes_per_day INTEGER CHECK(minutes_per_day IS NULL OR minutes_per_day BETWEEN 1 AND 1440),
 label TEXT NOT NULL, job_id TEXT REFERENCES b_jobs(id), created_by TEXT NOT NULL, created_at TEXT NOT NULL,
 CHECK(kind='leave' OR minutes_per_day IS NOT NULL)
);
CREATE INDEX b_capacity_blocks_span ON b_capacity_blocks(starts_on,ends_on);
ALTER TABLE b_jobs ADD COLUMN review_estimate_minutes INTEGER CHECK(review_estimate_minutes IS NULL OR review_estimate_minutes BETWEEN 1 AND 100000);

-- Firm work types and the status model (WORK-007). Each template has a work
-- type of the same name (created with the template); the firm adds others with
-- a default template, default budget and color. A job's stage is one of six:
-- Planned, Ready to start, In progress and Waiting while it is open (set by its
-- people), In review and Completed from its status (only through the review
-- gates). Firm sub-statuses sit under one stage and may be limited to work
-- types. Every stage or sub-status change is recorded with who, when, and the
-- old and new values. Additive only.
CREATE TABLE b_work_types(
 id TEXT PRIMARY KEY, name TEXT NOT NULL, template_id TEXT REFERENCES b_templates(id),
 budget_minutes INTEGER CHECK(budget_minutes IS NULL OR budget_minutes BETWEEN 1 AND 100000),
 color TEXT NOT NULL DEFAULT '#64748b' CHECK(color GLOB '#[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]'),
 created_by TEXT NOT NULL, created_at TEXT NOT NULL
);
INSERT INTO b_work_types(id,name,template_id,created_by,created_at) SELECT 'wt-'||id,name,id,created_by,created_at FROM b_templates;
CREATE TABLE b_sub_statuses(
 id TEXT PRIMARY KEY, stage TEXT NOT NULL CHECK(stage IN ('planned','ready','in_progress','waiting','in_review','completed')),
 name TEXT NOT NULL, work_types TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(work_types)),
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, deleted_by TEXT, deleted_at TEXT
);
ALTER TABLE b_jobs ADD COLUMN work_type_id TEXT REFERENCES b_work_types(id);
ALTER TABLE b_jobs ADD COLUMN open_stage TEXT CHECK(open_stage IS NULL OR open_stage IN ('planned','ready','in_progress','waiting'));
ALTER TABLE b_jobs ADD COLUMN sub_status_id TEXT REFERENCES b_sub_statuses(id);
DROP TRIGGER b_jobs_signed_off;
UPDATE b_jobs SET work_type_id='wt-'||template_id, open_stage='in_progress';
CREATE TRIGGER b_jobs_signed_off BEFORE UPDATE ON b_jobs WHEN OLD.status='signed_off' AND NEW.client_id IS OLD.client_id
 BEGIN SELECT RAISE(ABORT,'signed-off jobs are immutable'); END;
-- A sub-status always sits under the job's current stage, so none can stand in for the review gates.
CREATE TRIGGER b_jobs_sub_status BEFORE UPDATE ON b_jobs WHEN NEW.sub_status_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM b_sub_statuses s WHERE s.id=NEW.sub_status_id AND s.deleted_at IS NULL
  AND s.stage=CASE NEW.status WHEN 'review' THEN 'in_review' WHEN 'signed_off' THEN 'completed' ELSE NEW.open_stage END)
 BEGIN SELECT RAISE(ABORT,'sub-status does not belong to the job stage'); END;
CREATE TABLE b_job_status_history(
 id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES b_jobs(id),
 from_stage TEXT, from_sub_status_id TEXT, to_stage TEXT NOT NULL, to_sub_status_id TEXT, by TEXT NOT NULL, at TEXT NOT NULL
);
CREATE INDEX b_job_status_history_job ON b_job_status_history(job_id,at);
CREATE TRIGGER b_job_status_history_immutable BEFORE UPDATE ON b_job_status_history BEGIN SELECT RAISE(ABORT,'status history is immutable'); END;
CREATE TRIGGER b_job_status_history_delete BEFORE DELETE ON b_job_status_history BEGIN SELECT RAISE(ABORT,'status history is immutable'); END;
-- History starts from each job's current stage, at the time and by the person that put it there.
INSERT INTO b_job_status_history(id,job_id,to_stage,by,at)
 SELECT 'h-'||id,id,CASE status WHEN 'review' THEN 'in_review' WHEN 'signed_off' THEN 'completed' ELSE 'in_progress' END,
  COALESCE(signed_off_by,submitted_by,created_by),COALESCE(signed_off_at,submitted_at,created_at) FROM b_jobs;

-- WORK-007: each person's saved queue views (work type, stage, sub-status),
-- and an optional client-facing label per sub-status for the client link
-- (PORTAL-003). Additive only.
CREATE TABLE b_saved_views(
 id TEXT PRIMARY KEY, owner_email TEXT NOT NULL, name TEXT NOT NULL,
 filters TEXT NOT NULL CHECK(json_valid(filters)), created_at TEXT NOT NULL, UNIQUE(owner_email,name)
);
ALTER TABLE b_sub_statuses ADD COLUMN client_label TEXT CHECK(client_label IS NULL OR length(client_label) BETWEEN 1 AND 80);

-- WORK-007 job roles. A work type lists the roles its jobs need beyond
-- Preparer and Reviewer: Manager and Partner. A job that needs a Partner names
-- one (an active reviewer or the principal, never the preparer); the
-- reviewer's sign-off records the review and leaves the job In review for
-- partner sign-off, which only the partner or the principal completes or
-- returns. Additive only.
ALTER TABLE b_work_types ADD COLUMN roles TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(roles));
ALTER TABLE b_jobs ADD COLUMN partner_email TEXT;
ALTER TABLE b_jobs ADD COLUMN reviewed_by TEXT;
ALTER TABLE b_jobs ADD COLUMN reviewed_at TEXT;
CREATE TRIGGER b_jobs_partner_insert BEFORE INSERT ON b_jobs WHEN NEW.partner_email IS NOT NULL AND NEW.partner_email=NEW.preparer_email
 BEGIN SELECT RAISE(ABORT,'the partner cannot be the preparer'); END;
CREATE TRIGGER b_jobs_partner_update BEFORE UPDATE ON b_jobs WHEN NEW.partner_email IS NOT NULL AND NEW.partner_email=NEW.preparer_email
 BEGIN SELECT RAISE(ABORT,'the partner cannot be the preparer'); END;

-- WORK-006 personal plans, boards and calendars. A job carries a priority
-- (low, normal, high; normal by default) that boards and calendars filter by.
-- A person places their own jobs and tasks on days of their week (ordinal 0
-- is the job itself, otherwise one of its tasks). Each person's last board and
-- calendar filters are kept so they survive a refresh. Additive only.
ALTER TABLE b_jobs ADD COLUMN priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN ('low','normal','high'));
CREATE TABLE b_plan_items(
 id TEXT PRIMARY KEY, owner_email TEXT NOT NULL, day TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES b_jobs(id),
 ordinal INTEGER NOT NULL DEFAULT 0 CHECK(ordinal BETWEEN 0 AND 100), created_by TEXT NOT NULL, created_at TEXT NOT NULL,
 UNIQUE(owner_email,day,job_id,ordinal)
);
CREATE INDEX b_plan_items_owner ON b_plan_items(owner_email,day);
CREATE TABLE b_view_filters(
 owner_email TEXT NOT NULL, surface TEXT NOT NULL CHECK(surface IN ('board','calendar')),
 filters TEXT NOT NULL CHECK(json_valid(filters)), updated_at TEXT NOT NULL, PRIMARY KEY(owner_email,surface)
);

-- CAPACITY-002 coverage plans. A manager (a reviewer or the principal)
-- approves a previewed plan that moves an absent or overloaded person's work to
-- eligible colleagues and dates; work no one can cover is kept as a conflict
-- the approving manager owns until it is resolved or handed on. Additive only.
CREATE TABLE b_coverage_plans(
 id TEXT PRIMARY KEY, person_email TEXT NOT NULL, reason TEXT NOT NULL CHECK(reason IN ('leave','overload')),
 starts_on TEXT NOT NULL, ends_on TEXT NOT NULL, lines TEXT NOT NULL CHECK(json_valid(lines)),
 approved_by TEXT NOT NULL, approved_at TEXT NOT NULL
);
CREATE TABLE b_coverage_conflicts(
 id TEXT PRIMARY KEY, plan_id TEXT NOT NULL REFERENCES b_coverage_plans(id), job_id TEXT NOT NULL REFERENCES b_jobs(id),
 reason TEXT NOT NULL, owner_email TEXT NOT NULL, created_at TEXT NOT NULL,
 resolved_by TEXT, resolved_at TEXT, resolution TEXT,
 CHECK((resolved_at IS NULL) = (resolved_by IS NULL))
);
CREATE INDEX b_coverage_conflicts_job ON b_coverage_conflicts(job_id);

-- Existing amounts retain AUD without rewriting immutable history. Writers explicitly store new currency.
ALTER TABLE b_rates ADD COLUMN currency TEXT NOT NULL DEFAULT 'AUD' CHECK(currency IN ('USD','AUD'));
ALTER TABLE b_rate_cards ADD COLUMN currency TEXT NOT NULL DEFAULT 'AUD' CHECK(currency IN ('USD','AUD'));
ALTER TABLE b_templates ADD COLUMN currency TEXT NOT NULL DEFAULT 'AUD' CHECK(currency IN ('USD','AUD'));
ALTER TABLE b_jobs ADD COLUMN currency TEXT NOT NULL DEFAULT 'AUD' CHECK(currency IN ('USD','AUD'));
ALTER TABLE b_time ADD COLUMN currency TEXT NOT NULL DEFAULT 'AUD' CHECK(currency IN ('USD','AUD'));
ALTER TABLE b_mileage_rates ADD COLUMN currency TEXT NOT NULL DEFAULT 'AUD' CHECK(currency IN ('USD','AUD'));
ALTER TABLE b_expenses ADD COLUMN currency TEXT NOT NULL DEFAULT 'AUD' CHECK(currency IN ('USD','AUD'));
CREATE TRIGGER b_jobs_currency BEFORE UPDATE OF currency ON b_jobs WHEN NEW.currency IS NOT OLD.currency BEGIN SELECT RAISE(ABORT,'recorded currency is immutable'); END;
CREATE TRIGGER b_expenses_currency BEFORE UPDATE OF currency ON b_expenses WHEN NEW.currency IS NOT OLD.currency BEGIN SELECT RAISE(ABORT,'recorded currency is immutable'); END;
CREATE TRIGGER b_templates_currency BEFORE UPDATE OF currency ON b_templates WHEN NEW.currency IS NOT OLD.currency BEGIN SELECT RAISE(ABORT,'recorded currency is immutable'); END;
CREATE TRIGGER b_rate_cards_currency BEFORE UPDATE OF currency ON b_rate_cards WHEN NEW.currency IS NOT OLD.currency BEGIN SELECT RAISE(ABORT,'recorded currency is immutable'); END;
CREATE TRIGGER b_time_currency BEFORE UPDATE OF currency ON b_time WHEN NEW.currency IS NOT OLD.currency BEGIN SELECT RAISE(ABORT,'recorded currency is immutable'); END;

ALTER TABLE b_prospects ADD COLUMN currency TEXT NOT NULL DEFAULT 'AUD' CHECK(currency IN ('USD','AUD'));

-- CRM-005 public intake. Rate-limit digests and consumed tokens are ephemeral
-- installation-local spam checks and are excluded from portable archives.
CREATE TABLE b_intake_limits(id TEXT PRIMARY KEY, ip_digest TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE INDEX b_intake_limits_ip ON b_intake_limits(ip_digest,expires_at);
CREATE TABLE b_intake_tokens(digest TEXT PRIMARY KEY, expires_at INTEGER NOT NULL);
CREATE TABLE b_prospect_files(
 id TEXT PRIMARY KEY, prospect_id TEXT NOT NULL REFERENCES b_prospects(id),
 name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL CHECK(size BETWEEN 1 AND 1048576), sha256 TEXT NOT NULL,
 content_base64 TEXT, job_file_id TEXT REFERENCES b_files(id), uploaded_at TEXT NOT NULL, erased_at TEXT
);

ALTER TABLE b_templates ADD COLUMN starter_content TEXT;
ALTER TABLE b_jobs ADD COLUMN starter_content TEXT;
CREATE TABLE b_starter_adoptions(
 id TEXT PRIMARY KEY, library_id TEXT NOT NULL, version INTEGER NOT NULL,
 template_id TEXT NOT NULL UNIQUE REFERENCES b_templates(id), baseline TEXT NOT NULL CHECK(json_valid(baseline)),
