);
CREATE TABLE b_starter_releases(
 library_id TEXT NOT NULL, version INTEGER NOT NULL, snapshot TEXT NOT NULL CHECK(json_valid(snapshot)),
 source TEXT NOT NULL, published_by TEXT NOT NULL, published_at TEXT NOT NULL,
 PRIMARY KEY(library_id,version)
);
CREATE TRIGGER b_starter_release_immutable BEFORE UPDATE ON b_starter_releases BEGIN SELECT RAISE(ABORT,'library releases are immutable'); END;
CREATE TRIGGER b_starter_release_retained BEFORE DELETE ON b_starter_releases BEGIN SELECT RAISE(ABORT,'library releases are retained'); END;

-- CRM-001: authority belongs to the contact's relationship with this entity.
ALTER TABLE b_clients ADD COLUMN entity_type TEXT NOT NULL DEFAULT 'business' CHECK(entity_type IN ('individual','business','trust'));
ALTER TABLE b_clients ADD COLUMN lifecycle TEXT NOT NULL DEFAULT 'active' CHECK(lifecycle IN ('active','archived'));
ALTER TABLE b_clients ADD COLUMN archived_at TEXT;
ALTER TABLE b_clients ADD COLUMN archived_by TEXT;
ALTER TABLE b_clients ADD COLUMN partner_email TEXT NOT NULL DEFAULT '';
ALTER TABLE b_clients ADD COLUMN team TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(team));
ALTER TABLE b_clients ADD COLUMN services TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(services));
ALTER TABLE b_clients ADD COLUMN owner_client_id TEXT REFERENCES b_clients(id);
ALTER TABLE b_clients ADD COLUMN ssn_last4 TEXT NOT NULL DEFAULT '' CHECK(ssn_last4='' OR (length(ssn_last4)=4 AND ssn_last4 NOT GLOB '*[^0-9]*'));
ALTER TABLE b_prospects ADD COLUMN contacts TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(contacts));
CREATE TABLE b_client_contacts(
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES b_clients(id),
 name TEXT NOT NULL, first_name TEXT NOT NULL DEFAULT '', last_name TEXT NOT NULL DEFAULT '',
 email TEXT NOT NULL DEFAULT '' CHECK(email=lower(trim(email))), phone TEXT NOT NULL DEFAULT '',
 roles TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(roles)),
 authorized INTEGER NOT NULL DEFAULT 0 CHECK(authorized IN (0,1)), signer INTEGER NOT NULL DEFAULT 0 CHECK(signer IN (0,1)),
 portal INTEGER NOT NULL DEFAULT 0 CHECK(portal IN (0,1)), request_consent INTEGER NOT NULL DEFAULT 0 CHECK(request_consent IN (0,1)),
 email_consent INTEGER NOT NULL DEFAULT 0 CHECK(email_consent IN (0,1)), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),
 consent_note TEXT NOT NULL DEFAULT '', revision TEXT NOT NULL,
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_by TEXT NOT NULL, updated_at TEXT NOT NULL
);
CREATE UNIQUE INDEX b_contacts_entity_email ON b_client_contacts(client_id,email) WHERE email<>'' AND active=1;
CREATE INDEX b_contacts_email ON b_client_contacts(email);
CREATE INDEX b_contacts_phone ON b_client_contacts(phone) WHERE phone<>'';
ALTER TABLE b_portal_links ADD COLUMN contact_id TEXT REFERENCES b_client_contacts(id);
-- Existing clients retain their current, entity-specific collection permission.
INSERT INTO b_client_contacts(id,client_id,name,first_name,email,roles,authorized,portal,request_consent,email_consent,revision,created_by,created_at,updated_by,updated_at)
 SELECT 'legacy:'||id,id,contact_name,CASE WHEN instr(trim(contact_name),' ')>0 THEN substr(trim(contact_name),1,instr(trim(contact_name),' ')-1) ELSE trim(contact_name) END,
 lower(trim(contact_email)),'["primary"]',1,CASE WHEN contact_email<>'' THEN 1 ELSE 0 END,CASE WHEN contact_email<>'' THEN 1 ELSE 0 END,CASE WHEN contact_email<>'' THEN 1 ELSE 0 END,revision,'legacy migration',created_at,'legacy migration',created_at
 FROM b_clients WHERE contact_name<>'' OR contact_email<>'';
-- Legacy columns are a projection only. Inserts preserve archive/import revisions; contact commands explicitly advance them. Contact APIs never use them as identity.
CREATE TRIGGER b_contact_insert AFTER INSERT ON b_client_contacts BEGIN
 UPDATE b_clients SET revision=revision,contact_name=coalesce((SELECT name FROM b_client_contacts WHERE client_id=NEW.client_id AND active=1 AND authorized=1 AND EXISTS(SELECT 1 FROM json_each(roles) WHERE value='primary') ORDER BY created_at,id LIMIT 1),''),
 contact_email=coalesce((SELECT email FROM b_client_contacts WHERE client_id=NEW.client_id AND active=1 AND authorized=1 AND EXISTS(SELECT 1 FROM json_each(roles) WHERE value='primary') ORDER BY created_at,id LIMIT 1),'') WHERE id=NEW.client_id AND merged_into IS NULL;
END;
CREATE TRIGGER b_contact_update AFTER UPDATE ON b_client_contacts BEGIN
 UPDATE b_clients SET revision=lower(hex(randomblob(16))),contact_name=coalesce((SELECT name FROM b_client_contacts WHERE client_id=b_clients.id AND active=1 AND authorized=1 AND EXISTS(SELECT 1 FROM json_each(roles) WHERE value='primary') ORDER BY created_at,id LIMIT 1),''),
 contact_email=coalesce((SELECT email FROM b_client_contacts WHERE client_id=b_clients.id AND active=1 AND authorized=1 AND EXISTS(SELECT 1 FROM json_each(roles) WHERE value='primary') ORDER BY created_at,id LIMIT 1),'') WHERE id IN (OLD.client_id,NEW.client_id) AND merged_into IS NULL;
END;
CREATE TRIGGER b_contact_delete AFTER DELETE ON b_client_contacts BEGIN
 UPDATE b_clients SET revision=lower(hex(randomblob(16))),contact_name=coalesce((SELECT name FROM b_client_contacts WHERE client_id=OLD.client_id AND active=1 AND authorized=1 AND EXISTS(SELECT 1 FROM json_each(roles) WHERE value='primary') ORDER BY created_at,id LIMIT 1),''),
 contact_email=coalesce((SELECT email FROM b_client_contacts WHERE client_id=OLD.client_id AND active=1 AND authorized=1 AND EXISTS(SELECT 1 FROM json_each(roles) WHERE value='primary') ORDER BY created_at,id LIMIT 1),'') WHERE id=OLD.client_id AND merged_into IS NULL;
END;

-- PORTAL-004. Content and immutable submitted originals are portable; bearer
-- access continues to use excluded b_portal_links, never organizer content.
ALTER TABLE b_templates ADD COLUMN organizer TEXT CHECK(organizer IS NULL OR json_valid(organizer));
ALTER TABLE b_requests ADD COLUMN organizer_active INTEGER NOT NULL DEFAULT 1 CHECK(organizer_active IN (0,1));
CREATE TABLE b_organizer_versions(
 template_id TEXT NOT NULL REFERENCES b_templates(id), version INTEGER NOT NULL,
 definition TEXT NOT NULL CHECK(json_valid(definition)), author TEXT NOT NULL, created_at TEXT NOT NULL,
 PRIMARY KEY(template_id,version)
);
CREATE TRIGGER b_organizer_versions_immutable BEFORE UPDATE ON b_organizer_versions
 BEGIN SELECT RAISE(ABORT,'organizer versions are immutable'); END;
CREATE TABLE b_job_organizers(
 id TEXT PRIMARY KEY, job_id TEXT NOT NULL UNIQUE REFERENCES b_jobs(id),
 definition TEXT NOT NULL CHECK(json_valid(definition)), revision TEXT NOT NULL,
 sent_at TEXT, created_by TEXT NOT NULL, created_at TEXT NOT NULL,
 erased_at TEXT, erased_by TEXT, erase_reason TEXT
);
ALTER TABLE b_job_answers ADD COLUMN organizer_source TEXT REFERENCES b_job_organizers(id);
CREATE TABLE b_organizer_answers(
 organizer_id TEXT NOT NULL REFERENCES b_job_organizers(id), key TEXT NOT NULL,
 contact_id TEXT REFERENCES b_client_contacts(id), value TEXT, confirmed INTEGER NOT NULL DEFAULT 0 CHECK(confirmed IN (0,1)),
 carried_from TEXT, updated_by TEXT, updated_at TEXT,
 PRIMARY KEY(organizer_id,key)
);
CREATE TABLE b_organizer_submissions(
 id TEXT PRIMARY KEY, organizer_id TEXT NOT NULL REFERENCES b_job_organizers(id),
 version INTEGER NOT NULL, contact_id TEXT NOT NULL REFERENCES b_client_contacts(id),
 answers TEXT CHECK(answers IS NULL OR json_valid(answers)), submitted_at TEXT NOT NULL,
 reviewed_by TEXT, reviewed_at TEXT, review_note TEXT, erased_at TEXT,
 UNIQUE(organizer_id,version)
);
CREATE TRIGGER b_organizer_submissions_original BEFORE UPDATE ON b_organizer_submissions
 WHEN NEW.organizer_id<>OLD.organizer_id OR NEW.version<>OLD.version OR NEW.contact_id<>OLD.contact_id
 OR NEW.submitted_at<>OLD.submitted_at OR (NEW.answers IS NOT OLD.answers AND NOT(NEW.answers IS NULL AND NEW.erased_at IS NOT NULL))
 BEGIN SELECT RAISE(ABORT,'submitted organizer originals are immutable'); END;
CREATE TABLE b_organizer_requests(
 organizer_id TEXT NOT NULL REFERENCES b_job_organizers(id), key TEXT NOT NULL,
 request_id TEXT NOT NULL REFERENCES b_requests(id), PRIMARY KEY(organizer_id,key)
);
CREATE TABLE b_organizer_deliveries(
 id TEXT PRIMARY KEY, organizer_id TEXT NOT NULL REFERENCES b_job_organizers(id),
 contact_id TEXT NOT NULL REFERENCES b_client_contacts(id), to_email TEXT NOT NULL,
 subject TEXT NOT NULL, message TEXT NOT NULL, template_id TEXT, template_version INTEGER,
 attachments TEXT NOT NULL CHECK(json_valid(attachments)), delivery TEXT NOT NULL,
 sent_by TEXT NOT NULL, sent_at TEXT NOT NULL
);

-- VAULT-001: client credentials, sealed under the firm's vault key. The salt is
-- not secret (the key also needs the installation's SESSION_SECRET), so it
-- travels in archives with the ciphertext. archive_mode on each credential
-- mirrors the principal's choice so every archive path honours it per row.
CREATE TABLE b_vault_keys(
 id INTEGER PRIMARY KEY CHECK(id=1), salt TEXT NOT NULL,
 archive_mode TEXT NOT NULL CHECK(archive_mode IN ('encrypt','exclude')), set_by TEXT, set_at TEXT
);
CREATE TABLE b_vault_credentials(
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES b_clients(id), label TEXT NOT NULL, url TEXT NOT NULL,
 sealed TEXT, archive_mode TEXT NOT NULL CHECK(archive_mode IN ('encrypt','exclude')), rotate_by TEXT,
 created_by TEXT NOT NULL, created_at TEXT NOT NULL, updated_by TEXT NOT NULL, updated_at TEXT NOT NULL, revision INTEGER NOT NULL,
 erased_at TEXT, erased_by TEXT, erase_reason TEXT
);
CREATE INDEX b_vault_credentials_client ON b_vault_credentials(client_id,label);
-- Every reveal and every refused reveal of a credential the person could list.
CREATE TABLE b_vault_reveals(
 id TEXT PRIMARY KEY, credential_id TEXT NOT NULL, client_id TEXT NOT NULL, label TEXT NOT NULL,
 actor TEXT NOT NULL, outcome TEXT NOT NULL, at TEXT NOT NULL
);
CREATE INDEX b_vault_reveals_client ON b_vault_reveals(client_id,at);
-- A session's credential step-up (installation-local, never archived).
CREATE TABLE b_vault_stepups(session_id TEXT PRIMARY KEY, email TEXT NOT NULL, method TEXT NOT NULL, verified_at TEXT NOT NULL);

-- Sourced deadline rules, firm-defined rules, imported source revisions and
-- per-job calculated dates (DUE-001, DUE-003).
CREATE TABLE b_deadline_rules(
 key TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('agency','firm')),
 definition TEXT NOT NULL CHECK(json_valid(definition)), version TEXT NOT NULL, effective TEXT NOT NULL,
 source_url TEXT NOT NULL, source_title TEXT NOT NULL, revision_id TEXT,
 approved_by TEXT NOT NULL, approved_at TEXT NOT NULL
);
CREATE TABLE b_deadline_revisions(
 id TEXT PRIMARY KEY, version TEXT NOT NULL UNIQUE, effective TEXT NOT NULL, source_url TEXT NOT NULL, source_title TEXT NOT NULL,
 document TEXT NOT NULL CHECK(json_valid(document)), affected_jobs INTEGER NOT NULL, approved_by TEXT NOT NULL, approved_at TEXT NOT NULL
);
CREATE TABLE b_deadline_relief(
 id TEXT PRIMARY KEY, revision_id TEXT NOT NULL REFERENCES b_deadline_revisions(id), title TEXT NOT NULL, jurisdiction TEXT NOT NULL,
 states TEXT NOT NULL CHECK(json_valid(states)), rule_keys TEXT NOT NULL CHECK(json_valid(rule_keys)),
 from_date TEXT NOT NULL, to_date TEXT NOT NULL, postponed_to TEXT NOT NULL, source_url TEXT NOT NULL
);
CREATE TABLE b_client_obligations(
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES b_clients(id), rule_key TEXT NOT NULL REFERENCES b_deadline_rules(key),
 state TEXT NOT NULL CHECK(length(state)=2), fiscal_year_end INTEGER NOT NULL CHECK(fiscal_year_end BETWEEN 1 AND 12),
 internal_days INTEGER NOT NULL DEFAULT 0 CHECK(internal_days BETWEEN 0 AND 90), created_by TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE INDEX b_client_obligations_client ON b_client_obligations(client_id);
CREATE TABLE b_job_deadlines(
 job_id TEXT PRIMARY KEY REFERENCES b_jobs(id), obligation_id TEXT NOT NULL REFERENCES b_client_obligations(id),
 rule_key TEXT NOT NULL, rule_version TEXT NOT NULL, source_url TEXT NOT NULL, source_title TEXT NOT NULL, period_end TEXT NOT NULL,
 statutory_due TEXT NOT NULL, original_due TEXT NOT NULL, shift_note TEXT NOT NULL DEFAULT '',
 extension_form TEXT, extension_due TEXT, extension_automatic INTEGER NOT NULL DEFAULT 0,
 extension_recorded_by TEXT, extension_recorded_at TEXT,
 relief_id TEXT, relief_due TEXT, internal_due TEXT NOT NULL,
 override_due TEXT, override_reason TEXT, override_by TEXT, override_at TEXT,
 filing_submission_id TEXT, filing_file_id TEXT REFERENCES b_files(id), filing_accepted_on TEXT, filing_recorded_by TEXT, filing_recorded_at TEXT
);
-- WORK-002 recurrence rules may take each period's due date from a client obligation.
ALTER TABLE b_recurrence_rules ADD COLUMN obligation_id TEXT REFERENCES b_client_obligations(id);

-- Durable native automation: immutable approved definitions and transactional source events.
CREATE TABLE b_automation_rules(
 id TEXT PRIMARY KEY, family TEXT NOT NULL, version INTEGER NOT NULL, name TEXT NOT NULL,
 definition TEXT NOT NULL, budget INTEGER NOT NULL CHECK(budget>0), used INTEGER NOT NULL DEFAULT 0,
 status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','paused','revoked')),
 approved_by TEXT, principal_id TEXT, approved_at TEXT, after_seq INTEGER NOT NULL DEFAULT 0,
 created_at TEXT NOT NULL, UNIQUE(family,version)
);
CREATE TRIGGER b_automation_definition_immutable BEFORE UPDATE ON b_automation_rules
 WHEN OLD.definition<>NEW.definition OR OLD.budget<>NEW.budget OR OLD.version<>NEW.version OR OLD.family<>NEW.family
 BEGIN SELECT RAISE(ABORT,'immutable automation version'); END;
CREATE TABLE b_automation_events(
 seq INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL UNIQUE, job_id TEXT NOT NULL,
 kind TEXT NOT NULL, stage TEXT, sub_status_id TEXT, at TEXT NOT NULL
);
CREATE TABLE b_automation_attempts(
 id TEXT PRIMARY KEY, rule_id TEXT NOT NULL REFERENCES b_automation_rules(id), version INTEGER NOT NULL,
 event_key TEXT NOT NULL, job_id TEXT NOT NULL, status TEXT NOT NULL,
 outcome TEXT NOT NULL DEFAULT '', next_action TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL,
 UNIQUE(rule_id,event_key)
);
CREATE TRIGGER b_automation_status AFTER INSERT ON b_job_status_history BEGIN
 INSERT INTO b_automation_events(source,job_id,kind,stage,sub_status_id,at) VALUES('status:'||NEW.id,NEW.job_id,'status',NEW.to_stage,NEW.to_sub_status_id,NEW.at);
END;
CREATE TRIGGER b_automation_tasks AFTER UPDATE OF done_at ON b_job_steps
 WHEN NEW.done_at IS NOT NULL AND OLD.done_at IS NULL AND NOT EXISTS(SELECT 1 FROM b_job_steps WHERE job_id=NEW.job_id AND done_at IS NULL AND NOT EXISTS(SELECT 1 FROM b_job_answers a WHERE a.job_id=b_job_steps.job_id AND a.key=b_job_steps.when_question AND a.value IS NOT NULL AND a.value NOT IN (SELECT value FROM json_each(b_job_steps.when_values))))
 BEGIN INSERT OR IGNORE INTO b_automation_events(source,job_id,kind,at) VALUES('tasks:'||lower(hex(randomblob(16))),NEW.job_id,'tasks_complete',NEW.done_at); END;
CREATE TRIGGER b_automation_file AFTER INSERT ON b_files BEGIN
 INSERT INTO b_automation_events(source,job_id,kind,at) VALUES('file:'||NEW.id,NEW.job_id,'file',NEW.uploaded_at);
END;
CREATE TRIGGER b_automation_requests AFTER UPDATE OF status ON b_requests
 WHEN NEW.status='accepted' AND OLD.status<>'accepted' AND NOT EXISTS(SELECT 1 FROM b_requests WHERE job_id=NEW.job_id AND organizer_active=1 AND status<>'accepted')
 BEGIN INSERT OR IGNORE INTO b_automation_events(source,job_id,kind,at) VALUES('request:'||NEW.id||':'||NEW.updated_at,NEW.job_id,'request_complete',NEW.updated_at); END;
CREATE TRIGGER b_automation_organizer AFTER INSERT ON b_organizer_submissions BEGIN
 INSERT INTO b_automation_events(source,job_id,kind,at) SELECT 'organizer:'||NEW.id,job_id,'organizer_complete',NEW.submitted_at FROM b_job_organizers WHERE id=NEW.organizer_id;
END;
CREATE TRIGGER b_automation_proposal AFTER UPDATE OF status ON b_proposals
 WHEN OLD.status='pending' AND NEW.status<>'pending' AND json_extract(NEW.payload,'$.jobId') IS NOT NULL
 BEGIN INSERT INTO b_automation_events(source,job_id,kind,at) VALUES('proposal:'||NEW.id,json_extract(NEW.payload,'$.jobId'),'proposal',NEW.decided_at); END;

-- Views contain filters only. Internal schedules send live, permission-checked links.
CREATE TABLE b_report_views(id TEXT PRIMARY KEY,name TEXT NOT NULL,filters TEXT NOT NULL CHECK(json_valid(filters)),created_by TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE b_report_schedules(id TEXT PRIMARY KEY,view_id TEXT NOT NULL REFERENCES b_report_views(id),recipient TEXT NOT NULL,principal_id TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL,next_date TEXT NOT NULL,every_days INTEGER NOT NULL CHECK(every_days BETWEEN 1 AND 366),status TEXT NOT NULL CHECK(status IN ('active','paused')));
CREATE TABLE b_report_runs(id TEXT PRIMARY KEY,schedule_id TEXT NOT NULL REFERENCES b_report_schedules(id),due_date TEXT NOT NULL,at TEXT NOT NULL,notification_id TEXT NOT NULL,UNIQUE(schedule_id,due_date));

-- NOTIFY-001. Portable consumption history prevents restored audit records from
-- replaying alerts. Existing history predates activation and is already consumed.
CREATE TABLE b_notification_events(source_key TEXT PRIMARY KEY);
INSERT INTO b_notification_events(source_key) SELECT 'audit:'||id FROM b_audit;
-- Provider results can be recorded after the sending audit commits. Track the
-- actual delivery identity independently, including historical pending sends.
INSERT INTO b_notification_events(source_key) SELECT 'reminder:'||id FROM b_reminders;
INSERT INTO b_notification_events(source_key) SELECT 'deliverable:'||id FROM b_deliverable_versions;
INSERT INTO b_notification_events(source_key) SELECT 'organizer-delivery:'||id FROM b_organizer_deliveries;

CREATE TABLE b_notification_task_owners(job_id TEXT NOT NULL,ordinal INTEGER NOT NULL,email TEXT,PRIMARY KEY(job_id,ordinal));
INSERT INTO b_notification_task_owners SELECT j.id,s.ordinal,COALESCE(s.assignee_email,CASE s.assignee_role WHEN 'preparer' THEN j.preparer_email WHEN 'reviewer' THEN j.reviewer_email WHEN 'manager' THEN COALESCE(j.manager_email,j.reviewer_email) END) FROM b_job_steps s JOIN b_jobs j ON j.id=s.job_id;

CREATE TABLE b_notification_job_owners(job_id TEXT NOT NULL,email TEXT NOT NULL,PRIMARY KEY(job_id,email));
INSERT OR IGNORE INTO b_notification_job_owners SELECT j.id,p.value FROM b_jobs j JOIN json_each(json_array(j.preparer_email,j.reviewer_email,j.manager_email,j.partner_email)) p WHERE p.value IS NOT NULL;

-- NOTIFY-001. Preferences and delivery journals are practice data, never credentials.
ALTER TABLE b_notifications ADD COLUMN read_at TEXT;
CREATE TABLE b_notification_settings(email TEXT PRIMARY KEY,settings TEXT NOT NULL CHECK(json_valid(settings)));
CREATE TABLE b_notification_defaults(id INTEGER PRIMARY KEY CHECK(id=1),settings TEXT NOT NULL CHECK(json_valid(settings)));
CREATE TABLE b_notification_digests(email TEXT NOT NULL,local_date TEXT NOT NULL,delivery TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(email,local_date));

-- Bulk client messages and marketing consent (MSG-002; ct 20 Oct 21:21Z).
-- Each template version carries an immutable engagement or marketing class.
ALTER TABLE b_msg_template_versions ADD COLUMN message_class TEXT NOT NULL DEFAULT 'engagement' CHECK(message_class IN ('engagement','marketing'));

-- The append-only marketing consent log. Grants belong to one contact
-- relationship; withdrawals apply to the address across the whole firm.
CREATE TABLE b_marketing_consents(
 id TEXT PRIMARY KEY, contact_id TEXT REFERENCES b_client_contacts(id), client_id TEXT REFERENCES b_clients(id),
 address TEXT NOT NULL CHECK(address=lower(trim(address)) AND address<>''),
 purpose TEXT NOT NULL DEFAULT 'marketing' CHECK(purpose='marketing'),
 channel TEXT NOT NULL CHECK(channel IN ('email','portal')),
 kind TEXT NOT NULL CHECK(kind IN ('grant','withdraw','correction')),
 source TEXT NOT NULL CHECK(source IN ('intake_checkbox','portal_preference','staff_evidence','import','migration','unsubscribe_link','one_click','staff_reply','provider_complaint','owner_correction')),
 acted_at TEXT NOT NULL, recorded_at TEXT NOT NULL, actor TEXT NOT NULL,
 wording TEXT NOT NULL DEFAULT '', wording_version TEXT NOT NULL DEFAULT '', language TEXT NOT NULL DEFAULT 'en',
 evidence TEXT NOT NULL DEFAULT '', corrects_id TEXT REFERENCES b_marketing_consents(id), reason TEXT NOT NULL DEFAULT '',
 restored INTEGER NOT NULL DEFAULT 0 CHECK(restored IN (0,1)),
 CHECK(kind<>'grant' OR (contact_id IS NOT NULL AND wording<>'' AND wording_version<>'')),
 CHECK((kind='correction')=(source='owner_correction')),
 CHECK(kind<>'correction' OR (corrects_id IS NOT NULL AND reason<>'')),
 CHECK(source NOT IN ('staff_evidence','staff_reply') OR evidence<>'')
);
CREATE INDEX b_marketing_consents_address ON b_marketing_consents(address,acted_at);
CREATE INDEX b_marketing_consents_contact ON b_marketing_consents(contact_id);
CREATE UNIQUE INDEX b_marketing_consents_corrects ON b_marketing_consents(corrects_id) WHERE corrects_id IS NOT NULL;
CREATE TRIGGER b_marketing_consents_update BEFORE UPDATE ON b_marketing_consents BEGIN SELECT RAISE(ABORT,'consent events are immutable'); END;
CREATE TRIGGER b_marketing_consents_delete BEFORE DELETE ON b_marketing_consents BEGIN SELECT RAISE(ABORT,'consent events are immutable'); END;
-- The principal's confirmation that the consent log is current; installation-local, so a restore starts unconfirmed.
CREATE TABLE b_marketing_confirmations(id TEXT PRIMARY KEY, confirmed_by TEXT NOT NULL, confirmed_at TEXT NOT NULL, note TEXT NOT NULL);
-- A hard bounce marks an address invalid for both classes.
CREATE TABLE b_mail_suppressions(address TEXT PRIMARY KEY CHECK(address=lower(trim(address)) AND address<>''), reason TEXT NOT NULL, source_event TEXT NOT NULL, at TEXT NOT NULL);

-- A batch's class, template version and recipients are fixed at preview.
CREATE TABLE b_bulk_batches(
 id TEXT PRIMARY KEY, idempotency_key TEXT NOT NULL UNIQUE,
 class TEXT NOT NULL CHECK(class IN ('engagement','marketing')), channel TEXT NOT NULL DEFAULT 'email' CHECK(channel='email'),
 template_id TEXT NOT NULL REFERENCES b_msg_templates(id), template_version INTEGER NOT NULL,
 reason TEXT NOT NULL DEFAULT '', topic TEXT CHECK(topic IS NULL OR topic IN ('tax','other')), role TEXT NOT NULL DEFAULT 'primary',
 filter TEXT NOT NULL CHECK(json_valid(filter)), fingerprint TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('previewed','scheduled','sending','sent','paused')),
 send_at TEXT, chunk_size INTEGER NOT NULL DEFAULT 50 CHECK(chunk_size BETWEEN 1 AND 500),
 owner_email TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL,
 approved_by TEXT, approved_at TEXT, scheduled_by TEXT, scheduled_at TEXT,
 restore_review INTEGER NOT NULL DEFAULT 0 CHECK(restore_review IN (0,1)),
 CHECK(class<>'engagement' OR (reason<>'' AND topic IS NULL)), CHECK(class<>'marketing' OR topic IS NOT NULL),
 CHECK(class<>'marketing' OR status IN ('previewed','paused') OR approved_by IS NOT NULL)
);
CREATE TRIGGER b_bulk_batches_fixed BEFORE UPDATE ON b_bulk_batches
 WHEN NEW.class IS NOT OLD.class OR NEW.template_id IS NOT OLD.template_id OR NEW.template_version IS NOT OLD.template_version OR NEW.filter IS NOT OLD.filter OR NEW.fingerprint IS NOT OLD.fingerprint OR NEW.idempotency_key IS NOT OLD.idempotency_key
 BEGIN SELECT RAISE(ABORT,'immutable batch: class and recipients are fixed at preview'); END;
CREATE TABLE b_bulk_recipients(
 id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES b_bulk_batches(id), ordinal INTEGER NOT NULL,
 client_id TEXT NOT NULL REFERENCES b_clients(id), contact_id TEXT NOT NULL REFERENCES b_client_contacts(id),
 address TEXT NOT NULL, dedupe_key TEXT NOT NULL, basis TEXT NOT NULL DEFAULT '', job_id TEXT REFERENCES b_jobs(id),
 status TEXT NOT NULL CHECK(status IN ('pending','claimed','accepted','delivered','bounced','complained','held','failed','uncertain')),
 held_reason TEXT NOT NULL DEFAULT '', subject TEXT, body TEXT, provider_message_id TEXT, delivery TEXT NOT NULL DEFAULT '',
 attempt_id TEXT, attempted_at TEXT, misclassified_by TEXT, misclassified_at TEXT, misclassified_reason TEXT,
 UNIQUE(batch_id,dedupe_key), UNIQUE(batch_id,ordinal)
);
CREATE INDEX b_bulk_recipients_provider ON b_bulk_recipients(provider_message_id) WHERE provider_message_id IS NOT NULL;
CREATE TABLE b_bulk_exclusions(id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES b_bulk_batches(id), client_id TEXT NOT NULL REFERENCES b_clients(id), contact_id TEXT, address TEXT NOT NULL DEFAULT '', reason TEXT NOT NULL);
-- Provider delivery events, at most once per provider event.
CREATE TABLE b_bulk_events(
 id TEXT PRIMARY KEY, provider_event_id TEXT NOT NULL UNIQUE, recipient_id TEXT NOT NULL REFERENCES b_bulk_recipients(id),
 type TEXT NOT NULL CHECK(type IN ('delivered','bounced','complained')), detail TEXT NOT NULL DEFAULT '', occurred_at TEXT NOT NULL, recorded_at TEXT NOT NULL
);
-- Unsubscribe link secrets: only their digest, never archived.
CREATE TABLE b_unsubscribe_tokens(digest TEXT PRIMARY KEY, recipient_id TEXT NOT NULL REFERENCES b_bulk_recipients(id), address TEXT NOT NULL, created_at TEXT NOT NULL);

-- Contact-merge consent (MSG-002 carried by CRM-004; ct 20 Oct 21:21Z): when two contacts merge,
-- the most restrictive consent wins. While the merge stands, the surviving contact's marketing
-- grants acted at or before the merge stop counting when the merged contact held no current
-- grant; a grant the contact gives later revives marketing. Undo deletes the merge's holds.
CREATE TABLE b_marketing_merge_holds(
 merge_id TEXT NOT NULL REFERENCES b_client_merges(id), contact_id TEXT NOT NULL REFERENCES b_client_contacts(id),
 merged_contact_id TEXT NOT NULL REFERENCES b_client_contacts(id), held_at TEXT NOT NULL,
 PRIMARY KEY(merge_id,contact_id)
);
CREATE INDEX b_marketing_merge_holds_contact ON b_marketing_merge_holds(contact_id,held_at);

-- MSG-002 freezes only organizer identity/revision, never answers or bearer links.
ALTER TABLE b_bulk_batches ADD COLUMN attach_organizer INTEGER NOT NULL DEFAULT 0 CHECK(attach_organizer IN (0,1));
ALTER TABLE b_bulk_recipients ADD COLUMN organizer_id TEXT REFERENCES b_job_organizers(id);
ALTER TABLE b_bulk_recipients ADD COLUMN organizer_revision TEXT;
CREATE TRIGGER b_bulk_organizer_fixed BEFORE UPDATE ON b_bulk_batches
 WHEN NEW.attach_organizer IS NOT OLD.attach_organizer
 BEGIN SELECT RAISE(ABORT,'immutable batch: organizer attachment fixed at preview'); END;
CREATE TRIGGER b_bulk_recipient_organizer_fixed BEFORE UPDATE ON b_bulk_recipients
 WHEN NEW.organizer_id IS NOT OLD.organizer_id OR NEW.organizer_revision IS NOT OLD.organizer_revision
 BEGIN SELECT RAISE(ABORT,'immutable recipient: organizer fixed at preview'); END;

-- MSG-002: any restored practice needs the existing principal consent-log confirmation,
-- including an empty log whose pending reviewed import later supplies opt-ins.
ALTER TABLE b_meta ADD COLUMN marketing_restore_review INTEGER NOT NULL DEFAULT 0 CHECK(marketing_restore_review IN (0,1));

-- TIME-003: preserve template rates and add more specific work-type targets.
CREATE TABLE b_rate_cards_next(
 id TEXT PRIMARY KEY,
 scope TEXT NOT NULL CHECK(scope IN ('client_service','client','service','staff','role')),
 person_email TEXT, role TEXT CHECK(role IS NULL OR role IN ('owner','reviewer','preparer')),
 work_type_id TEXT REFERENCES b_work_types(id),
 template_id TEXT REFERENCES b_templates(id), client_id TEXT REFERENCES b_clients(id),
 rate_cents INTEGER NOT NULL CHECK(rate_cents BETWEEN 0 AND 1000000), effective_from TEXT NOT NULL,
 currency TEXT NOT NULL DEFAULT 'AUD' CHECK(currency IN ('USD','AUD')),
 created_by TEXT NOT NULL, created_at TEXT NOT NULL,
 CHECK(scope<>'client_service' OR (client_id IS NOT NULL AND ((template_id IS NOT NULL AND work_type_id IS NULL) OR (template_id IS NULL AND work_type_id IS NOT NULL)) AND person_email IS NULL AND role IS NULL)),
 CHECK(scope<>'client' OR (work_type_id IS NULL AND client_id IS NOT NULL AND template_id IS NULL AND person_email IS NULL AND role IS NULL)),
 CHECK(scope<>'service' OR (((template_id IS NOT NULL AND work_type_id IS NULL) OR (template_id IS NULL AND work_type_id IS NOT NULL)) AND client_id IS NULL AND person_email IS NULL AND role IS NULL)),
 CHECK(scope<>'staff' OR (work_type_id IS NULL AND person_email IS NOT NULL AND client_id IS NULL AND template_id IS NULL AND role IS NULL)),
 CHECK(scope<>'role' OR (work_type_id IS NULL AND role IS NOT NULL AND client_id IS NULL AND template_id IS NULL AND person_email IS NULL))
);
INSERT INTO b_rate_cards_next(id,scope,person_email,role,template_id,client_id,rate_cents,effective_from,created_by,created_at,currency) SELECT id,scope,person_email,role,template_id,client_id,rate_cents,effective_from,created_by,created_at,currency FROM b_rate_cards;
DROP TABLE b_rate_cards;
ALTER TABLE b_rate_cards_next RENAME TO b_rate_cards;
CREATE INDEX b_rate_cards_lookup ON b_rate_cards(scope,effective_from);

-- MSG-001: every message made from a template carries that version's files and
-- records their name, type, size and SHA-256. Bulk recipients and portal
-- messages join document reminders and organizer invitations. Additive only.
ALTER TABLE b_bulk_recipients ADD COLUMN attachments TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(attachments));
-- A portal message composed from a template keeps its rendered subject, the
-- version used and the files the client may download from their link.
ALTER TABLE b_portal_items ADD COLUMN subject TEXT;
ALTER TABLE b_portal_items ADD COLUMN template_id TEXT REFERENCES b_msg_templates(id);
ALTER TABLE b_portal_items ADD COLUMN template_version INTEGER;
ALTER TABLE b_portal_items ADD COLUMN template_edited INTEGER NOT NULL DEFAULT 0 CHECK(template_edited IN (0,1));
ALTER TABLE b_portal_items ADD COLUMN attachments TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(attachments));

-- ERASURE-002: principal-set retention and holds, recorded external copies, hashed
-- withdrawal suppressions and whole-client erasure receipts.
ALTER TABLE b_clients ADD COLUMN erased_at TEXT;

-- A retention mark names one record the principal keeps: a client, one job or one file.
-- 'hold' lasts until the principal releases it; 'retain' lasts until an explicit date.
-- Nothing expires or deletes by itself.
CREATE TABLE b_retention_marks(
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES b_clients(id),
 scope TEXT NOT NULL CHECK(scope IN ('client','job','file')), target_id TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('hold','retain')), until TEXT,
 reason TEXT NOT NULL CHECK(reason<>''), placed_by TEXT NOT NULL, placed_at TEXT NOT NULL,
 released_by TEXT, released_at TEXT, release_reason TEXT,
 CHECK((kind='retain')=(until IS NOT NULL)), CHECK((released_by IS NULL)=(released_at IS NULL))
);
CREATE INDEX b_retention_marks_client ON b_retention_marks(client_id,released_at);

-- A copy of client data outside this installation. Blotter never deletes it; the named holder does.
CREATE TABLE b_external_copies(
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES b_clients(id),
 kind TEXT NOT NULL CHECK(kind IN ('document','provider','buyer')),
 system TEXT NOT NULL CHECK(system<>''), holder TEXT NOT NULL CHECK(holder<>''), note TEXT NOT NULL DEFAULT '',
 recorded_by TEXT NOT NULL, recorded_at TEXT NOT NULL, closed_by TEXT, closed_at TEXT, closed_note TEXT,
 CHECK((closed_by IS NULL)=(closed_at IS NULL))
);
CREATE INDEX b_external_copies_client ON b_external_copies(client_id);

-- One-way digest of a withdrawn or bounced address. The address itself is erased.
CREATE TABLE b_erased_suppressions(
 digest TEXT PRIMARY KEY CHECK(length(digest)=64), reason TEXT NOT NULL, erasure_id TEXT NOT NULL, at TEXT NOT NULL
);

-- The erasure journal: counts and named exceptions only, never a stored value.
CREATE TABLE b_client_erasures(
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL UNIQUE REFERENCES b_clients(id), client_ref TEXT NOT NULL,
 reason TEXT NOT NULL, plan_hash TEXT NOT NULL, requested_by TEXT NOT NULL, approved_by TEXT NOT NULL, approved_at TEXT NOT NULL,
 counts TEXT NOT NULL CHECK(json_valid(counts)), retained TEXT NOT NULL CHECK(json_valid(retained)), journal_epoch INTEGER NOT NULL
);
-- What each step matched when it ran, counted by its own predicate inside the erasure batch.
CREATE TABLE b_client_erasure_steps(
 erasure_id TEXT NOT NULL REFERENCES b_client_erasures(id), ordinal INTEGER NOT NULL, table_name TEXT NOT NULL,
 action TEXT NOT NULL CHECK(action IN ('redact','delete','cascade')), label TEXT NOT NULL, count INTEGER NOT NULL, PRIMARY KEY(erasure_id,ordinal)
);

-- ERASURE-002 policy (ct 22 Oct 2026): scoped holds with owner and review date, extend-only
-- retain-until marks, per-class retention periods, practitioner-recorded signed engagements,
-- the sealed retained-records remainder, confirmed expiry, deletion requests and subjects other
-- than a whole client. Nothing here expires or deletes by itself.

-- Marks are rebuilt: class and firm-wide scopes, a hold owner and a review date.
ALTER TABLE b_retention_marks RENAME TO b_retention_marks_c34;
DROP INDEX b_retention_marks_client;
CREATE TABLE b_retention_marks(
 id TEXT PRIMARY KEY, client_id TEXT REFERENCES b_clients(id),
 scope TEXT NOT NULL CHECK(scope IN ('client','job','file','engagement','export','class')), target_id TEXT, class TEXT,
 kind TEXT NOT NULL CHECK(kind IN ('hold','retain')), until TEXT, owner TEXT, review_date TEXT,
 reason TEXT NOT NULL CHECK(reason<>''), placed_by TEXT NOT NULL, placed_at TEXT NOT NULL,
 released_by TEXT, released_at TEXT, release_reason TEXT,
 CHECK((kind='retain')=(until IS NOT NULL)), CHECK((released_by IS NULL)=(released_at IS NULL)),
 CHECK(kind<>'hold' OR (owner IS NOT NULL AND review_date IS NOT NULL)),
 CHECK((scope='class')=(class IS NOT NULL)), CHECK(scope='class' OR (client_id IS NOT NULL AND (scope='client' OR target_id IS NOT NULL)))
);
INSERT INTO b_retention_marks(id,client_id,scope,target_id,kind,until,owner,review_date,reason,placed_by,placed_at,released_by,released_at,release_reason)
 SELECT id,client_id,scope,CASE WHEN scope='client' THEN NULL ELSE target_id END,kind,until,CASE WHEN kind='hold' THEN placed_by END,CASE WHEN kind='hold' THEN date(substr(placed_at,1,10),'+1 year') END,
  reason,placed_by,placed_at,released_by,released_at,release_reason FROM b_retention_marks_c34;
DROP TABLE b_retention_marks_c34;
CREATE INDEX b_retention_marks_client ON b_retention_marks(client_id,released_at);

-- Retention period in whole years for a retained class; absent means the default of 7.
CREATE TABLE b_retention_periods(
 class TEXT PRIMARY KEY CHECK(class IN ('signed_work','engagement','efile_auth','signed_documents','billing')),
 years INTEGER NOT NULL CHECK(years BETWEEN 1 AND 100), reason TEXT NOT NULL CHECK(reason<>''), set_by TEXT NOT NULL, set_at TEXT NOT NULL
);

-- A signed engagement the principal files, labelled honestly: it was not signed through Blotter.
CREATE TABLE b_engagements(
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES b_clients(id), title TEXT NOT NULL, signers TEXT NOT NULL CHECK(json_valid(signers)),
 signed_date TEXT NOT NULL, label TEXT NOT NULL, name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL CHECK(size BETWEEN 1 AND 1048576),
 sha256 TEXT NOT NULL, content_base64 TEXT, recorded_by TEXT NOT NULL, recorded_at TEXT NOT NULL, erased_at TEXT
);
CREATE INDEX b_engagements_client ON b_engagements(client_id);

-- A subject's request to the principal: who asked, how, when, how it was verified and why.
CREATE TABLE b_deletion_requests(
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES b_clients(id), subject_kind TEXT NOT NULL CHECK(subject_kind IN ('client','contact','prospect')), subject_id TEXT NOT NULL,
 requester TEXT NOT NULL CHECK(requester<>''), channel TEXT NOT NULL CHECK(channel<>''), received_on TEXT NOT NULL, verification TEXT NOT NULL CHECK(verification<>''),
 reason TEXT NOT NULL CHECK(reason<>''), recorded_by TEXT NOT NULL, recorded_at TEXT NOT NULL, erasure_id TEXT
);

-- The erasure receipts are rebuilt without UNIQUE(client_id): a held run can be followed by another,
-- and one subject may be a contact or a prospect instead of the whole client.
CREATE TABLE b_tmp_erasure_steps AS SELECT * FROM b_client_erasure_steps;
DROP TABLE b_client_erasure_steps;
CREATE TABLE b_tmp_erasures AS SELECT * FROM b_client_erasures;
DROP TABLE b_client_erasures;
CREATE TABLE b_client_erasures(
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES b_clients(id), client_ref TEXT NOT NULL,
 subject_kind TEXT NOT NULL DEFAULT 'client' CHECK(subject_kind IN ('client','contact','prospect')), subject_id TEXT, request_id TEXT,
 reason TEXT NOT NULL, plan_hash TEXT NOT NULL, requested_by TEXT NOT NULL, approved_by TEXT NOT NULL, approved_at TEXT NOT NULL,
 counts TEXT NOT NULL CHECK(json_valid(counts)), retained TEXT NOT NULL CHECK(json_valid(retained)), journal_epoch INTEGER NOT NULL
);
INSERT INTO b_client_erasures(id,client_id,client_ref,subject_kind,subject_id,reason,plan_hash,requested_by,approved_by,approved_at,counts,retained,journal_epoch)
 SELECT id,client_id,client_ref,'client',client_id,reason,plan_hash,requested_by,approved_by,approved_at,counts,retained,journal_epoch FROM b_tmp_erasures;
CREATE TABLE b_client_erasure_steps(
 erasure_id TEXT NOT NULL REFERENCES b_client_erasures(id), ordinal INTEGER NOT NULL, table_name TEXT NOT NULL,
 action TEXT NOT NULL CHECK(action IN ('redact','delete','cascade')), label TEXT NOT NULL, count INTEGER NOT NULL, PRIMARY KEY(erasure_id,ordinal)
);
INSERT INTO b_client_erasure_steps SELECT * FROM b_tmp_erasure_steps;
DROP TABLE b_tmp_erasure_steps; DROP TABLE b_tmp_erasures;
CREATE INDEX b_client_erasures_client ON b_client_erasures(client_id);

-- The legal name, taxpayer identifier and address a retained record needs, sealed under the vault key.
-- Read only through the principal's audited retained-records door.
CREATE TABLE b_retained_identity(
 client_id TEXT PRIMARY KEY REFERENCES b_clients(id), sealed TEXT NOT NULL, erasure_id TEXT NOT NULL, at TEXT NOT NULL
);
CREATE TABLE b_retained_reads(
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES b_clients(id), action TEXT NOT NULL CHECK(action IN ('read','export')),
 actor TEXT NOT NULL, reason TEXT NOT NULL CHECK(reason<>''), at TEXT NOT NULL
);

-- A retained record whose period ended and that the principal confirmed for erasure.
CREATE TABLE b_expiry_erasures(
 id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('job','engagement','export')), record_id TEXT NOT NULL, client_id TEXT REFERENCES b_clients(id),
 reason TEXT NOT NULL CHECK(reason<>''), confirmed_by TEXT NOT NULL, confirmed_at TEXT NOT NULL, counts TEXT NOT NULL CHECK(json_valid(counts)), journal_epoch INTEGER NOT NULL,
 UNIQUE(kind,record_id)
);

-- Explicit per-person scopes preserve existing staff authority until configured.
-- A scoped person with no grants has no client access. Removing a team does
-- not restore legacy firm-wide authority.
CREATE TABLE b_access_policy(id INTEGER PRIMARY KEY CHECK(id=1),revision TEXT NOT NULL);
CREATE TABLE b_access_members(email TEXT PRIMARY KEY,scoped INTEGER NOT NULL DEFAULT 1 CHECK(scoped=1),read_only INTEGER NOT NULL DEFAULT 0 CHECK(read_only IN(0,1)));
CREATE TABLE b_access_teams(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE b_access_team_members(team_id TEXT NOT NULL REFERENCES b_access_teams(id) ON DELETE CASCADE,email TEXT NOT NULL,PRIMARY KEY(team_id,email));
CREATE TABLE b_access_team_clients(team_id TEXT NOT NULL REFERENCES b_access_teams(id) ON DELETE CASCADE,client_id TEXT NOT NULL REFERENCES b_clients(id),PRIMARY KEY(team_id,client_id));
CREATE TABLE b_access_grants(email TEXT NOT NULL,client_id TEXT NOT NULL REFERENCES b_clients(id),PRIMARY KEY(email,client_id));
CREATE VIEW b_access_effective AS SELECT email,client_id FROM b_access_grants UNION SELECT m.email,c.client_id FROM b_access_team_members m JOIN b_access_team_clients c ON c.team_id=m.team_id;
CREATE TABLE b_sensitive_documents(file_key TEXT PRIMARY KEY,classification TEXT NOT NULL,reason TEXT NOT NULL,updated_by TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE b_sensitive_grants(file_key TEXT NOT NULL REFERENCES b_sensitive_documents(file_key) ON DELETE CASCADE,email TEXT NOT NULL,PRIMARY KEY(file_key,email));
CREATE TABLE b_access_stepups(session_id TEXT PRIMARY KEY,email TEXT NOT NULL,method TEXT NOT NULL,verified_at TEXT NOT NULL);

-- BILL-002: native USD invoice authority. Drafts reserve sources; issued documents
-- and their supplied tax treatment are snapshots, independent of job completion.
CREATE TABLE b_invoice_settings(
 id INTEGER PRIMARY KEY CHECK(id=1), authority TEXT NOT NULL CHECK(authority='blotter'),
 revision TEXT NOT NULL, authorized_by TEXT NOT NULL, authorized_at TEXT NOT NULL, reason TEXT NOT NULL
);
CREATE TABLE b_invoice_retainers(
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES b_clients(id), job_id TEXT NOT NULL REFERENCES b_jobs(id),
 title TEXT NOT NULL, start_month TEXT NOT NULL, cancelled_from TEXT,
 definition TEXT NOT NULL CHECK(json_valid(definition)), revision TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('active','paused','cancelled')), principal_id TEXT,
 owner_email TEXT NOT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL
);
CREATE TABLE b_invoice_amendments(
 id TEXT PRIMARY KEY, retainer_id TEXT NOT NULL REFERENCES b_invoice_retainers(id),
 effective_month TEXT NOT NULL, before_snapshot TEXT NOT NULL CHECK(json_valid(before_snapshot)),
 after_snapshot TEXT NOT NULL CHECK(json_valid(after_snapshot)), reason TEXT NOT NULL,
 authorized_by TEXT NOT NULL, authorized_at TEXT NOT NULL, UNIQUE(retainer_id,effective_month)
);
CREATE TABLE b_invoice_entitlements(
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES b_clients(id), job_id TEXT NOT NULL REFERENCES b_jobs(id),
 kind TEXT NOT NULL CHECK(kind IN ('fixed','milestone','proration','retainer')),
 reference TEXT NOT NULL, description TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents BETWEEN 1 AND 100000000),
 currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency='USD'), source_key TEXT NOT NULL UNIQUE,
 retainer_id TEXT REFERENCES b_invoice_retainers(id), period TEXT, authorized_by TEXT NOT NULL,
 authorized_at TEXT NOT NULL, authorization TEXT NOT NULL, UNIQUE(job_id,reference), UNIQUE(retainer_id,period)
);
CREATE UNIQUE INDEX b_invoice_fixed_job ON b_invoice_entitlements(job_id) WHERE kind='fixed';
CREATE TABLE b_invoices(
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES b_clients(id), job_id TEXT NOT NULL REFERENCES b_jobs(id),
 title TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('draft','issued','void')),
 number INTEGER UNIQUE, currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency='USD'),
 snapshot TEXT NOT NULL CHECK(json_valid(snapshot)), subtotal_cents INTEGER NOT NULL,
 tax_cents INTEGER NOT NULL CHECK(tax_cents>=0), credit_cents INTEGER NOT NULL CHECK(credit_cents>=0),
 total_cents INTEGER NOT NULL CHECK(total_cents>=0), revision TEXT NOT NULL,
 owner_email TEXT NOT NULL, issue_date TEXT NOT NULL, due_date TEXT NOT NULL,
 retainer_id TEXT REFERENCES b_invoice_retainers(id), period TEXT,
 prepared_by TEXT NOT NULL, prepared_at TEXT NOT NULL, issued_by TEXT, issued_at TEXT,
 pdf_base64 TEXT, pdf_sha256 TEXT, voided_by TEXT, voided_at TEXT, void_reason TEXT,
 erased_at TEXT, UNIQUE(retainer_id,period), CHECK(status<>'issued' OR number IS NOT NULL)
);
CREATE INDEX b_invoices_client ON b_invoices(client_id,status);
CREATE TABLE b_invoice_sources(
 source_key TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES b_invoices(id), job_id TEXT NOT NULL REFERENCES b_jobs(id),
 entitlement_id TEXT REFERENCES b_invoice_entitlements(id)
);
-- Reservations are shared with BILL-001, including a fixed entitlement's fee:<job>.
CREATE TRIGGER b_invoice_source_reserve BEFORE INSERT ON b_invoice_sources
 WHEN EXISTS(SELECT 1 FROM b_export_sources WHERE source_key=NEW.source_key)
 BEGIN SELECT RAISE(ABORT,'source already reserved by billing export'); END;
CREATE TRIGGER b_export_invoice_reserve BEFORE INSERT ON b_export_sources
 WHEN EXISTS(SELECT 1 FROM b_invoice_sources WHERE source_key=NEW.source_key)
 BEGIN SELECT RAISE(ABORT,'source already reserved by invoice'); END;
CREATE TRIGGER b_invoice_sources_release BEFORE DELETE ON b_invoice_sources
 WHEN NOT EXISTS(SELECT 1 FROM b_invoices WHERE id=OLD.invoice_id AND status='void' AND number IS NULL)
 BEGIN SELECT RAISE(ABORT,'issued invoice sources are permanent'); END;
CREATE TRIGGER b_invoice_time_delete BEFORE DELETE ON b_time
 WHEN EXISTS(SELECT 1 FROM b_invoice_sources WHERE source_key='time:'||OLD.id)
 BEGIN SELECT RAISE(ABORT,'invoiced time is immutable'); END;
CREATE TABLE b_invoice_credits(
 id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES b_clients(id),
 kind TEXT NOT NULL CHECK(kind IN ('deposit','credit')), reference TEXT NOT NULL,
 amount_cents INTEGER NOT NULL CHECK(amount_cents BETWEEN 1 AND 100000000), currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency='USD'),
 reason TEXT NOT NULL, recorded_by TEXT NOT NULL, recorded_at TEXT NOT NULL, UNIQUE(client_id,reference)
);
CREATE TABLE b_invoice_credit_uses(
 id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES b_invoices(id), credit_id TEXT NOT NULL REFERENCES b_invoice_credits(id),
 amount_cents INTEGER NOT NULL CHECK(amount_cents>0)
);
CREATE TRIGGER b_invoice_credit_available BEFORE INSERT ON b_invoice_credit_uses
 WHEN NOT EXISTS(SELECT 1 FROM b_invoice_credits c JOIN b_invoices i ON i.id=NEW.invoice_id WHERE c.id=NEW.credit_id AND c.client_id=i.client_id
 AND NEW.amount_cents<=c.amount_cents-COALESCE((SELECT sum(u.amount_cents) FROM b_invoice_credit_uses u JOIN b_invoices x ON x.id=u.invoice_id WHERE u.credit_id=c.id AND x.status<>'void'),0))
 BEGIN SELECT RAISE(ABORT,'credit is unavailable'); END;
CREATE TABLE b_invoice_deliveries(
 id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES b_invoices(id), contact_id TEXT NOT NULL REFERENCES b_client_contacts(id),
 contact_revision TEXT NOT NULL, recipient_email TEXT NOT NULL, recipient_name TEXT NOT NULL,
 digest TEXT NOT NULL UNIQUE, expires_at TEXT NOT NULL, revoked_at TEXT,
 status TEXT NOT NULL CHECK(status IN ('dispatching','accepted','failed','held')),
 delivery TEXT NOT NULL, subject TEXT NOT NULL, message TEXT NOT NULL,
 sent_by TEXT NOT NULL, sent_at TEXT NOT NULL, resolved_by TEXT, resolved_at TEXT, resolution TEXT
);
CREATE INDEX b_invoice_deliveries_invoice ON b_invoice_deliveries(invoice_id,sent_at);
CREATE TRIGGER b_invoice_document_immutable BEFORE UPDATE ON b_invoices
 WHEN OLD.status IN ('issued','void') AND (NEW.number IS NOT OLD.number OR NEW.snapshot IS NOT OLD.snapshot
 OR NEW.subtotal_cents IS NOT OLD.subtotal_cents OR NEW.tax_cents IS NOT OLD.tax_cents OR NEW.credit_cents IS NOT OLD.credit_cents
 OR NEW.total_cents IS NOT OLD.total_cents OR NEW.currency IS NOT OLD.currency OR NEW.pdf_base64 IS NOT OLD.pdf_base64
 OR NEW.pdf_sha256 IS NOT OLD.pdf_sha256 OR NEW.issue_date IS NOT OLD.issue_date OR NEW.due_date IS NOT OLD.due_date
 OR NEW.issued_at IS NOT OLD.issued_at OR NEW.issued_by IS NOT OLD.issued_by OR NEW.prepared_at IS NOT OLD.prepared_at
 OR NEW.prepared_by IS NOT OLD.prepared_by OR NEW.status NOT IN (OLD.status,'void'))
 BEGIN SELECT RAISE(ABORT,'issued invoice is immutable'); END;
CREATE TRIGGER b_invoice_delete BEFORE DELETE ON b_invoices
 BEGIN SELECT RAISE(ABORT,'invoice history is immutable'); END;

