 secondary_document TEXT, note TEXT, recorded_by TEXT NOT NULL, recorded_at TEXT NOT NULL,
 PRIMARY KEY(request_id,attempt,contact_id)
);

-- BILL-004: the firm's overdue-invoice reminder schedule runs only under a recorded
-- consent of the principal or a financial-authority holder; clients may opt out or
-- use their own steps; a dispute or payment plan stops reminders for that invoice.
-- Each invoice reminds once per schedule step: a passed step is either sent or
-- recorded as skipped, and a held send is never replayed.
CREATE TABLE b_invoice_reminder_policy(
 id INTEGER PRIMARY KEY CHECK(id=1), offsets TEXT NOT NULL CHECK(json_valid(offsets)),
 template_id TEXT NOT NULL, template_version INTEGER NOT NULL,
 status TEXT NOT NULL CHECK(status IN('active','paused')), revision TEXT NOT NULL,
 consenter_id TEXT, consented_by TEXT NOT NULL, reason TEXT NOT NULL, consented_at TEXT NOT NULL
);
CREATE TABLE b_invoice_reminder_clients(
 client_id TEXT PRIMARY KEY REFERENCES b_clients(id), mode TEXT NOT NULL CHECK(mode IN('off','custom')),
 offsets TEXT CHECK(offsets IS NULL OR json_valid(offsets)), reason TEXT NOT NULL, set_by TEXT NOT NULL, set_at TEXT NOT NULL
);
ALTER TABLE b_invoices ADD COLUMN collection_hold TEXT CHECK(collection_hold IS NULL OR collection_hold IN('disputed','payment_plan'));
ALTER TABLE b_invoices ADD COLUMN collection_note TEXT;
CREATE TABLE b_invoice_reminders(
 id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES b_invoices(id), step INTEGER NOT NULL, scheduled_on TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN('dispatching','accepted','failed','held','skipped')),
 recipient_email TEXT, subject TEXT, message TEXT, delivery TEXT, policy_revision TEXT NOT NULL, created_at TEXT NOT NULL,
 UNIQUE(invoice_id,step)
);

-- BILL-003: an approved write-off discharges part of an issued invoice's balance. It is
-- its own immutable record: the issued invoice, its PDF and its totals never change.
CREATE TABLE b_invoice_writeoffs(
 id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL REFERENCES b_invoices(id), client_id TEXT NOT NULL REFERENCES b_clients(id),
 amount_cents INTEGER NOT NULL CHECK(amount_cents BETWEEN 1 AND 100000000), currency TEXT NOT NULL DEFAULT 'USD' CHECK(currency='USD'),
 reason TEXT NOT NULL CHECK(reason<>''), approved_by TEXT NOT NULL, approved_at TEXT NOT NULL
);
CREATE INDEX b_invoice_writeoffs_invoice ON b_invoice_writeoffs(invoice_id,approved_at);
CREATE TRIGGER b_invoice_writeoff_open BEFORE INSERT ON b_invoice_writeoffs
 WHEN NOT EXISTS(SELECT 1 FROM b_invoices i WHERE i.id=NEW.invoice_id AND i.status='issued' AND i.erased_at IS NULL AND i.client_id=NEW.client_id
 AND NEW.amount_cents<=i.subtotal_cents+i.tax_cents-COALESCE((SELECT sum(u.amount_cents) FROM b_invoice_credit_uses u WHERE u.invoice_id=i.id),0)
 -COALESCE((SELECT sum(w.amount_cents) FROM b_invoice_writeoffs w WHERE w.invoice_id=i.id),0))
 BEGIN SELECT RAISE(ABORT,'write-off exceeds the open balance'); END;
CREATE TRIGGER b_invoice_writeoff_immutable BEFORE UPDATE ON b_invoice_writeoffs
 WHEN NEW.amount_cents IS NOT OLD.amount_cents OR NEW.invoice_id IS NOT OLD.invoice_id OR NEW.approved_at IS NOT OLD.approved_at OR NEW.approved_by IS NOT OLD.approved_by
 BEGIN SELECT RAISE(ABORT,'a write-off is immutable'); END;
CREATE TRIGGER b_invoice_writeoff_delete BEFORE DELETE ON b_invoice_writeoffs
 BEGIN SELECT RAISE(ABORT,'write-off history is immutable'); END;

