 invited_by TEXT NOT NULL, invited_at TEXT NOT NULL, accepted_at TEXT, revoked_by TEXT, revoked_at TEXT, revoke_reason TEXT
);
CREATE INDEX b_portal_grants_account ON b_portal_grants(account_id);
