CREATE INDEX b_integration_limits_window ON b_integration_limits(key_id,at);
CREATE TABLE b_integration_writes(key_id TEXT NOT NULL REFERENCES b_integration_keys(id),key_digest TEXT NOT NULL,payload_digest TEXT NOT NULL,client_id TEXT NOT NULL REFERENCES b_clients(id),job_id TEXT NOT NULL REFERENCES b_jobs(id),ordinal INTEGER NOT NULL,at TEXT NOT NULL,PRIMARY KEY(key_id,key_digest));

CREATE TABLE b_integration_hooks(
 id TEXT PRIMARY KEY,key_id TEXT NOT NULL REFERENCES b_integration_keys(id),label TEXT NOT NULL,
 destination_sealed TEXT,secret_sealed TEXT,status TEXT NOT NULL CHECK(status IN ('active','revoked','inactive')),
 created_by TEXT NOT NULL,created_at TEXT NOT NULL,start_row INTEGER NOT NULL
);
CREATE TABLE b_integration_deliveries(
 id TEXT PRIMARY KEY,hook_id TEXT NOT NULL REFERENCES b_integration_hooks(id),event_id TEXT NOT NULL,
 client_id TEXT NOT NULL REFERENCES b_clients(id),job_id TEXT NOT NULL REFERENCES b_jobs(id),
 status TEXT NOT NULL CHECK(status IN ('pending','dispatching','delivered','failed','held','record_erased','revoked')),
 attempts INTEGER NOT NULL DEFAULT 0,outcome TEXT NOT NULL DEFAULT '',next_action TEXT NOT NULL DEFAULT '',
 attempted_at TEXT,finished_at TEXT,UNIQUE(hook_id,event_id)
);

-- Enterprise policy is optional; the principal always retains native recovery.
CREATE TABLE b_enterprise_connection(id INTEGER PRIMARY KEY CHECK(id=1),tenant TEXT NOT NULL,required INTEGER NOT NULL CHECK(required IN(0,1)),require_mfa INTEGER NOT NULL CHECK(require_mfa IN(0,1)),active INTEGER NOT NULL CHECK(active IN(0,1)),revision INTEGER NOT NULL DEFAULT 1,principal_id TEXT,token_digest TEXT);
CREATE TABLE b_enterprise_identities(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,subject TEXT NOT NULL UNIQUE,external_id TEXT UNIQUE,display_name TEXT NOT NULL DEFAULT '',blocked INTEGER NOT NULL DEFAULT 0 CHECK(blocked IN(0,1)),active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE b_enterprise_groups(id TEXT PRIMARY KEY,display_name TEXT NOT NULL);
CREATE TABLE b_enterprise_group_members(group_id TEXT NOT NULL REFERENCES b_enterprise_groups(id) ON DELETE CASCADE,identity_id TEXT NOT NULL REFERENCES b_enterprise_identities(id) ON DELETE CASCADE,PRIMARY KEY(group_id,identity_id));
CREATE TABLE b_enterprise_mappings(group_id TEXT PRIMARY KEY,role TEXT NOT NULL CHECK(role IN('preparer','reviewer')),team_id TEXT REFERENCES b_access_teams(id));
CREATE TABLE b_enterprise_team_grants(team_id TEXT NOT NULL,email TEXT NOT NULL,PRIMARY KEY(team_id,email));
CREATE TABLE b_enterprise_sessions(session_id TEXT PRIMARY KEY,identity_id TEXT NOT NULL REFERENCES b_enterprise_identities(id),revision INTEGER NOT NULL,mfa INTEGER NOT NULL CHECK(mfa IN(0,1)));

-- Portal staging shares the existing nonportable seven-day transport only.
-- Completion keeps ordinary file custody, clocks, holds and erasure fencing.
ALTER TABLE b_document_uploads ADD COLUMN portal_link_id TEXT REFERENCES b_portal_links(id);
ALTER TABLE b_document_uploads ADD COLUMN portal_contact_id TEXT REFERENCES b_client_contacts(id);
ALTER TABLE b_document_uploads ADD COLUMN portal_contact_revision TEXT;
CREATE INDEX b_document_uploads_portal ON b_document_uploads(portal_link_id,request_id,expires_at);
CREATE TRIGGER b_portal_packet_grant_revoked AFTER UPDATE OF revoked_at ON b_portal_grants
 WHEN NEW.revoked_at IS NOT NULL AND OLD.revoked_at IS NULL BEGIN
 DELETE FROM b_document_uploads WHERE portal_contact_id=NEW.contact_id;
END;
